import { memo, useEffect, useRef, useState } from "react";
import { useVideoEditorServices } from "./video-editor-context";
import type { MediaClip } from "./types";

function AudioClipWaveformView({ clip }: { clip: MediaClip }) {
  const { loadWaveform } = useVideoEditorServices();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [waveform, setWaveform] = useState<{
    url: string;
    peaks: number[];
  } | null>(null);
  useEffect(() => {
    if (!loadWaveform) return;
    let active = true;
    void loadWaveform(clip.source.url)
      .then((peaks) => {
        if (active) setWaveform({ url: clip.source.url, peaks });
      })
      .catch(() => {
        // The clip remains editable if optional waveform decoding is unavailable.
      });
    return () => {
      active = false;
    };
  }, [clip.source.url, loadWaveform]);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !waveform || waveform.url !== clip.source.url) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const from = Math.floor(
      (clip.in / clip.source.duration) * waveform.peaks.length,
    );
    const to = Math.max(
      from + 1,
      Math.ceil((clip.out / clip.source.duration) * waveform.peaks.length),
    );
    const peaks = waveform.peaks.slice(from, to);
    const peakMax = Math.max(0.01, ...peaks);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = getComputedStyle(canvas)
      .getPropertyValue("--edit-waveform")
      .trim();
    ctx.beginPath();
    ctx.moveTo(0, canvas.height);
    peaks.forEach((peak, i) =>
      ctx.lineTo(
        (i / Math.max(1, peaks.length - 1)) * canvas.width,
        canvas.height - Math.max(1, (peak / peakMax) * (canvas.height - 4)),
      ),
    );
    ctx.lineTo(canvas.width, canvas.height);
    ctx.closePath();
    ctx.fill();
  }, [waveform, clip.in, clip.out, clip.source.duration, clip.source.url]);
  return (
    <>
      {(!waveform || waveform.url !== clip.source.url) && (
        <span className="truncate px-3 text-[color:var(--ui-text-secondary)]">
          {clip.source.label}
        </span>
      )}
      <canvas
        ref={canvasRef}
        width={1200}
        height={48}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 h-full w-full"
      />
    </>
  );
}

export const AudioClipWaveform = memo(AudioClipWaveformView);

import type { MediaClip } from "./types";

export function audioEnvelope(clip: MediaClip) {
  const range = clip.fadeRange ?? clip;
  const duration = (range.out - range.in) / range.speed;
  return {
    offset: (clip.in - range.in) / range.speed,
    rate: clip.speed / range.speed,
    duration,
    fadeIn: Math.min(clip.fadeIn, duration),
    fadeOut: Math.min(clip.fadeOut, duration),
  };
}

import type { ReactNode } from "react";
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "./internal/components/ui/context-menu";
import { useI18n } from "./video-editor-context";
import {
  clipDuration,
  duplicateClip,
  moveVideo,
  normalizeEdit,
  splitClip,
} from "./timeline";
import type { EditClip, VideoEditDocument } from "./types";

export function ClipContextMenu({
  children,
  clip,
  doc,
  time,
  disabled,
  onCommit,
  onSelect,
}: {
  children: ReactNode;
  clip: EditClip;
  doc: VideoEditDocument;
  time: number;
  disabled: boolean;
  onCommit: (doc: VideoEditDocument) => void;
  onSelect: (id: string) => void;
}) {
  const { t } = useI18n();
  const update = (next: EditClip) =>
    onCommit({
      ...doc,
      clips: doc.clips.map((c) => (c.id === clip.id ? next : c)),
    });
  return (
    <ContextMenu>
      <ContextMenuTrigger
        asChild
        disabled={disabled}
        onContextMenu={() => onSelect(clip.id)}
      >
        {children}
      </ContextMenuTrigger>
      <ContextMenuContent className="video-editor z-[var(--ui-z-overlay-popover)]">
        <ContextMenuItem
          disabled={
            time <= clip.start || time >= clip.start + clipDuration(clip)
          }
          onSelect={() =>
            onCommit(splitClip(doc, clip.id, time, crypto.randomUUID()))
          }
        >
          {t("videoEditor.split")}
        </ContextMenuItem>
        <ContextMenuItem
          onSelect={() => {
            const id = crypto.randomUUID();
            const next = duplicateClip(doc, clip.id, id);
            if (next === doc) return;
            onCommit(next);
            onSelect(id);
          }}
        >
          {t("videoEditor.duplicate")}
        </ContextMenuItem>
        {clip.kind !== "text" && (
          <ContextMenuItem
            onSelect={() => update({ ...clip, muted: !clip.muted })}
          >
            {t(clip.muted ? "videoEditor.unmute" : "videoEditor.mute")}
          </ContextMenuItem>
        )}
        {clip.kind === "video" && (
          <>
            <ContextMenuItem
              onSelect={() => onCommit(moveVideo(doc, clip.id, -1))}
            >
              {t("videoEditor.earlier")}
            </ContextMenuItem>
            <ContextMenuItem
              onSelect={() => onCommit(moveVideo(doc, clip.id, 1))}
            >
              {t("videoEditor.later")}
            </ContextMenuItem>
            <ContextMenuItem
              onSelect={() => update({ ...clip, transform: undefined })}
            >
              {t("videoEditor.resetTransform")}
            </ContextMenuItem>
          </>
        )}
        <ContextMenuSeparator />
        <ContextMenuItem
          variant="destructive"
          onSelect={() =>
            onCommit(
              normalizeEdit({
                ...doc,
                clips: doc.clips.filter((c) => c.id !== clip.id),
              }),
            )
          }
        >
          {t("videoEditor.delete")}
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  );
}

import { X } from "lucide-react";
import { Textarea } from "./internal/components/ui/textarea";
import { useI18n } from "./video-editor-context";
import { clipDuration, MIN_CLIP_DURATION } from "./timeline";
import { EditNumberField } from "./edit-number-field";
import { EditIconButton } from "./edit-icon-button";
import { TextStyleControls } from "./text-style-controls";
import type { EditClip } from "./types";

export function ClipProperties({
  clip,
  timelineDuration,
  disabled,
  onChange,
  onClose,
}: {
  clip?: EditClip;
  timelineDuration: number;
  disabled: boolean;
  onChange: (clip: EditClip) => void;
  onClose: () => void;
}) {
  const { t } = useI18n();
  const number = (
    label: string,
    value: number,
    min: number,
    max: number,
    change: (n: number) => void,
    unit?: string,
    step = 0.1,
  ) => (
    <EditNumberField
      key={`${clip?.id}:${label}`}
      label={label}
      value={value}
      min={min}
      max={max}
      sliderMax={max === 36000 ? Math.max(10, timelineDuration, value) : max}
      disabled={disabled}
      onChange={change}
      unit={unit}
      step={step}
    />
  );
  if (!clip)
    return (
      <div className="grid h-full place-items-center text-[color:var(--ui-text-muted)]">
        {t("videoEditor.selectText")}
      </div>
    );
  return (
    <div className="flex h-full min-h-0 flex-col">
      <header className="flex h-12 shrink-0 items-center justify-between border-b border-[var(--ui-border-subtle)] px-4">
        <h2 className="font-medium">{t(`videoEditor.${clip.kind}`)}</h2>
        <EditIconButton label="closeProperties" icon={X} onClick={onClose} />
      </header>
      <div className="min-h-0 flex-1 overflow-auto p-4">
        <div className="flex flex-col gap-5">
          {clip.kind === "text" ? (
            <>
              <Textarea
                aria-label={t("videoEditor.textContent")}
                value={clip.text}
                disabled={disabled}
                maxLength={1000}
                className="min-h-24 resize-none border-0 bg-[var(--ui-bg-control)]"
                onChange={(e) => onChange({ ...clip, text: e.target.value })}
              />
              <TextStyleControls
                clip={clip}
                disabled={disabled}
                onChange={onChange}
              />
              <div className="flex flex-col gap-3 border-t border-[var(--ui-border-subtle)] pt-5">
                {number(
                  "start",
                  clip.start,
                  0,
                  36000,
                  (start) => onChange({ ...clip, start }),
                  "s",
                )}
                {number(
                  "duration",
                  clip.duration,
                  MIN_CLIP_DURATION,
                  36000,
                  (duration) => onChange({ ...clip, duration }),
                  "s",
                )}
              </div>
            </>
          ) : (
            <>
              <section className="flex flex-col gap-3">
                <h3 className="mb-2 font-medium">
                  {t("videoEditor.speedSection")}
                </h3>
                {number(
                  "speed",
                  clip.speed,
                  0.25,
                  4,
                  (speed) => onChange({ ...clip, speed }),
                  "x",
                  0.25,
                )}
                {number(
                  "duration",
                  clipDuration(clip),
                  (clip.out - clip.in) / 4,
                  (clip.out - clip.in) / 0.25,
                  (duration) =>
                    onChange({
                      ...clip,
                      speed: (clip.out - clip.in) / duration,
                    }),
                  "s",
                )}
              </section>
              <section className="flex flex-col gap-3 border-t border-[var(--ui-border-subtle)] pt-5">
                <h3 className="mb-2 font-medium">
                  {t("videoEditor.volumeSection")}
                </h3>
                {number(
                  "gain",
                  clip.volume > 0 ? 20 * Math.log10(clip.volume) : -60,
                  -60,
                  0,
                  (db) =>
                    onChange({
                      ...clip,
                      volume: db <= -60 ? 0 : 10 ** (db / 20),
                    }),
                  "dB",
                )}
                {clip.kind === "audio" && (
                  <>
                    {number(
                      "fadeIn",
                      clip.fadeIn,
                      0,
                      clipDuration(clip),
                      (fadeIn) => onChange({ ...clip, fadeIn }),
                      "s",
                    )}
                    {number(
                      "fadeOut",
                      clip.fadeOut,
                      0,
                      clipDuration(clip),
                      (fadeOut) => onChange({ ...clip, fadeOut }),
                      "s",
                    )}
                  </>
                )}
              </section>
              <details className="border-t border-[var(--ui-border-subtle)] pt-4">
                <summary className="cursor-pointer text-[color:var(--ui-text-secondary)]">
                  {t("videoEditor.trimSection")}
                </summary>
                <div className="mt-3 flex flex-col gap-3">
                  {clip.kind === "audio" &&
                    number(
                      "start",
                      clip.start,
                      0,
                      36000,
                      (start) => onChange({ ...clip, start }),
                      "s",
                    )}
                  {number(
                    "trimIn",
                    clip.in,
                    0,
                    clip.out - MIN_CLIP_DURATION * clip.speed,
                    (value) => onChange({ ...clip, in: value }),
                    "s",
                  )}
                  {number(
                    "trimOut",
                    clip.out,
                    clip.in + MIN_CLIP_DURATION * clip.speed,
                    clip.source.duration,
                    (out) => onChange({ ...clip, out }),
                    "s",
                  )}
                </div>
              </details>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import type { TextClip } from "./types";

/** Shared by preview and exported PNG overlays, including system CJK font fallback. */
export function drawEditText(
  ctx: CanvasRenderingContext2D,
  clip: TextClip,
  width: number,
  height: number,
) {
  ctx.save();
  const fontSize = (clip.fontSize * height) / 1080;
  ctx.font = `${clip.italic ? "italic " : ""}${clip.bold === false ? 400 : 600} ${fontSize}px sans-serif`;
  ctx.textAlign = clip.align ?? "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = clip.color;
  const lines = clip.text.split("\n");
  if (clip.textType === "subtitle") {
    ctx.strokeStyle = "#000000";
    ctx.lineWidth = Math.max(1, fontSize / 12);
    ctx.lineJoin = "round";
  }
  lines.forEach((line, i) => {
    if (clip.textType === "subtitle")
      ctx.strokeText(
        line,
        clip.x * width,
        clip.y * height + (i - (lines.length - 1) / 2) * fontSize * 1.25,
        width * 0.95,
      );
    ctx.fillText(
      line,
      clip.x * width,
      clip.y * height + (i - (lines.length - 1) / 2) * fontSize * 1.25,
      width * 0.95,
    );
  });
  ctx.restore();
}
export async function textOverlay(
  clip: TextClip | TextClip[],
  width: number,
  height: number,
) {
  await document.fonts.ready;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Canvas unavailable");
  for (const item of Array.isArray(clip) ? clip : [clip])
    drawEditText(ctx, item, width, height);
  const blob = await new Promise<Blob>((resolve, reject) =>
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error("Text rendering failed"))),
      "image/png",
    ),
  );
  return new Uint8Array(await blob.arrayBuffer());
}

export function editTextBounds(clip: TextClip, width: number, height: number) {
  const ctx = document.createElement("canvas").getContext("2d");
  const font = (clip.fontSize * height) / 1080;
  if (ctx)
    ctx.font = `${clip.italic ? "italic " : ""}${clip.bold === false ? 400 : 600} ${font}px sans-serif`;
  const lines = clip.text.split("\n");
  const w = Math.min(
    width * 0.95,
    Math.max(
      font,
      ...lines.map((line) => ctx?.measureText(line).width ?? font),
    ),
  );
  const h = font * 1.25 * lines.length;
  let left = clip.x * width - w / 2;
  if (clip.align === "left") left = clip.x * width;
  if (clip.align === "right") left = clip.x * width - w;
  return { x: left, y: clip.y * height - h / 2, width: w, height: h };
}

import { Button } from "./internal/components/ui/button";
import { Spinner } from "./internal/components/ui/spinner";
import { useI18n } from "./video-editor-context";

export function EditBusyOverlay({ onCancel }: { onCancel: () => void }) {
  const { t } = useI18n();
  return (
    <div
      className="absolute inset-0 z-[var(--ui-z-overlay-popover)] grid place-items-center bg-[var(--ui-bg-app)]/70 p-4"
      onKeyDown={(event) => event.stopPropagation()}
    >
      <div className="flex w-full max-w-sm flex-col items-center gap-5 rounded-[var(--ui-radius-xl)] border border-[var(--ui-border-subtle)] bg-[var(--ui-bg-surface-raised)] p-6 shadow-[var(--ui-shadow-dialog)]">
        <div
          role="status"
          className="flex flex-col items-center gap-3 text-center"
        >
          <Spinner
            aria-hidden="true"
            aria-label={undefined}
            role="presentation"
            className="size-6 text-[color:var(--ui-text-secondary)] motion-reduce:animate-none"
          />
          <span>{t("videoEditor.loading")}</span>
        </div>
        <Button autoFocus variant="ghost" onClick={onCancel}>
          {t("videoEditor.cancel")}
        </Button>
      </div>
    </div>
  );
}

import { useRef, useState } from "react";
import {
  autoUpdate,
  flip,
  offset,
  shift,
  useFloating,
} from "@floating-ui/react";
import { ChevronDown } from "lucide-react";
import { Button } from "./internal/components/ui/button";
import { Spinner } from "./internal/components/ui/spinner";
import { Dialog, DialogContent, DialogTitle } from "./internal/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "./internal/components/ui/select";
import { useI18n } from "./video-editor-context";
import type { VideoEditorExportSettings } from "./types";

export function EditExportMenu({
  disabled,
  loading = false,
  actions,
  recommendedResolution,
  onExport,
}: {
  disabled: boolean;
  loading?: boolean;
  actions: { id: string; label: string }[];
  recommendedResolution?: VideoEditorExportSettings["resolution"];
  onExport: (destination: string, settings: VideoEditorExportSettings) => void;
}) {
  const { t } = useI18n();
  const [open, setOpen] = useState(false);
  const [destination, setDestination] = useState(actions[0]?.id ?? "");
  const [chosenResolution, setResolution] =
    useState<VideoEditorExportSettings["resolution"]>();
  const resolution = chosenResolution ?? recommendedResolution ?? 1080;
  const [format, setFormat] =
    useState<VideoEditorExportSettings["format"]>("mp4");
  const trigger = useRef<HTMLButtonElement>(null);
  const { refs, floatingStyles } = useFloating({
    open,
    placement: "bottom-end",
    strategy: "fixed",
    whileElementsMounted: autoUpdate,
    middleware: [offset(8), flip(), shift({ padding: 12 })],
  });
  if (!actions.length) return null;
  const selectedDestination = actions.some(
    (action) => action.id === destination,
  )
    ? destination
    : actions[0].id;
  const field = (
    label: string,
    value: string,
    options: { value: string; label: string }[],
    onValueChange: (value: string) => void,
  ) => (
    <div className="grid grid-cols-[6rem_minmax(0,1fr)] items-center gap-4">
      <span className="text-[color:var(--ui-text-secondary)]">
        {t(`videoEditor.${label}`)}
      </span>
      <Select value={value} onValueChange={onValueChange}>
        <SelectTrigger
          aria-label={t(`videoEditor.${label}`)}
          className="h-10 rounded-[var(--ui-radius-lg)] border-0 bg-[var(--ui-bg-control)] text-sm"
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent className="video-editor">
          {options.map((option) => (
            <SelectItem
              key={option.value}
              value={option.value}
              className="text-sm"
            >
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
  return (
    <Dialog open={open && !disabled && !loading} onOpenChange={setOpen}>
      <Button
        ref={(element) => {
          trigger.current = element;
          refs.setReference(element);
        }}
        variant="outline"
        disabled={disabled || loading}
        aria-haspopup="dialog"
        aria-expanded={open && !disabled && !loading}
        aria-busy={loading || undefined}
        aria-label={t(
          loading ? "videoEditor.exportingButton" : "videoEditor.exportMenu",
        )}
        onClick={() => setOpen(true)}
        className="h-9 gap-2 border-0 bg-[var(--ui-text-primary)] px-4 text-[color:var(--ui-bg-app)] hover:bg-[var(--ui-text-primary)]/90 hover:text-[color:var(--ui-bg-app)] active:bg-[var(--ui-text-primary)]/80"
      >
        {loading ? (
          <>
            <Spinner
              aria-hidden="true"
              aria-label={undefined}
              role="presentation"
              className="size-4 motion-reduce:animate-none"
            />
            <span role="status">{t("videoEditor.exportingButton")}</span>
          </>
        ) : (
          <>
            {t("videoEditor.exportMenu")}
            <ChevronDown className="size-3" />
          </>
        )}
      </Button>
      <DialogContent
        ref={refs.setFloating}
        style={floatingStyles}
        showCloseButton={false}
        showOverlay={false}
        aria-describedby={undefined}
        onKeyDown={(event) => event.stopPropagation()}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
          trigger.current?.focus({ preventScroll: true });
        }}
        className="video-editor left-0 top-0 flex w-[360px] max-w-[calc(100vw-2rem)] translate-x-0 translate-y-0 flex-col gap-5 rounded-[var(--ui-radius-xl)] border-0 bg-[var(--ui-bg-surface)] p-4 text-sm"
      >
        <DialogTitle className="font-medium text-[color:var(--ui-text-muted)]">
          {t("videoEditor.exportSettings")}
        </DialogTitle>
        {field(
          "exportDestination",
          selectedDestination,
          actions.map((action) => ({ value: action.id, label: action.label })),
          setDestination,
        )}
        <div className="flex flex-col gap-4 border-t border-[var(--ui-border-subtle)] pt-5">
          {field(
            "exportResolution",
            String(resolution),
            [480, 720, 1080].map((value) => ({
              value: String(value),
              label:
                value === recommendedResolution
                  ? t("videoEditor.recommendedResolution", {
                      resolution: value,
                    })
                  : `${value}P`,
            })),
            (value) => {
              if (value === "480" || value === "720" || value === "1080")
                setResolution(
                  Number(value) as VideoEditorExportSettings["resolution"],
                );
            },
          )}
          {field(
            "exportContainer",
            format,
            [
              { value: "mp4", label: "MP4" },
              { value: "mov", label: "MOV" },
            ],
            (value) => {
              if (value === "mp4" || value === "mov") setFormat(value);
            },
          )}
        </div>
        <div className="grid grid-cols-2 gap-2">
          <Button
            variant="ghost"
            onClick={() => setOpen(false)}
            className="h-10 bg-[var(--ui-bg-control)]"
          >
            {t("videoEditor.cancel")}
          </Button>
          <Button
            disabled={disabled || loading}
            onClick={() => {
              setOpen(false);
              onExport(selectedDestination, { resolution, format });
            }}
            className="h-10 bg-[var(--ui-text-primary)] text-[color:var(--ui-bg-app)] hover:bg-[var(--ui-text-primary)]/90 hover:text-[color:var(--ui-bg-app)]"
          >
            {t("videoEditor.confirmExport")}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import type { ComponentType, SVGProps } from "react";
import { Button } from "./internal/components/ui/button";
import { TooltipLabel } from "./internal/components/ui/tooltip";
import { useI18n } from "./video-editor-context";
import { cn } from "./internal/lib/utils";

export function EditIconButton({
  label,
  icon: Icon,
  active,
  disabled,
  onClick,
  className,
}: {
  label: string;
  icon: ComponentType<
    Pick<SVGProps<SVGSVGElement>, "className" | "strokeWidth">
  >;
  active?: boolean;
  disabled?: boolean;
  onClick: () => void;
  className?: string;
}) {
  const { t } = useI18n();
  const name = t(`videoEditor.${label}`);
  return (
    <TooltipLabel content={name}>
      <Button
        variant="ghost"
        size="icon"
        aria-label={name}
        aria-pressed={active}
        disabled={disabled}
        onClick={onClick}
        className={cn(
          "size-8 shrink-0 text-[color:var(--ui-text-secondary)]",
          active && "bg-[var(--ui-bg-control-active)] text-[color:var(--ui-text-primary)]",
          className,
        )}
      >
        <Icon className="size-4" strokeWidth={1.7} />
      </Button>
    </TooltipLabel>
  );
}

import { useState } from "react";
import { Input } from "./internal/components/ui/input";
import { FluidSlider } from "./internal/components/ui/range-slider-fluid";
import { useI18n } from "./video-editor-context";

export function EditNumberField({
  label,
  value,
  min,
  max,
  sliderMax = max,
  step = 0.1,
  unit,
  disabled,
  onChange,
}: {
  label: string;
  value: number;
  min: number;
  max: number;
  sliderMax?: number;
  step?: number;
  unit?: string;
  disabled: boolean;
  onChange: (value: number) => void;
}) {
  const { t } = useI18n();
  const [draft, setDraft] = useState<{ base: number; text: string } | null>(
    null,
  );
  const activeDraft = draft?.base === value ? draft : null;
  const precision = Math.min(
    6,
    Math.max(2, String(step).split(".")[1]?.length ?? 0),
  );
  const text = activeDraft?.text ?? String(Number(value.toFixed(precision)));
  const parsed = Number(text);
  const current = text.trim() && Number.isFinite(parsed) ? parsed : value;
  const commit = (next: number) => {
    setDraft(null);
    if (disabled || !Number.isFinite(next)) return;
    const clean = Math.max(min, Math.min(max, next));
    if (clean !== value) onChange(clean);
  };
  const commitInput = () => {
    if (!activeDraft) return;
    if (text.trim()) commit(parsed);
    else setDraft(null);
  };
  return (
    <FluidSlider
      className="bg-[var(--ui-bg-control)] hover:bg-[var(--ui-bg-control-hover)]"
      label={t(`videoEditor.${label}`)}
      min={min}
      max={Math.min(max, Math.max(sliderMax, value))}
      step={step}
      value={current}
      disabled={disabled}
      format={(next) => `${Number(next.toFixed(precision))}${unit ?? ""}`}
      onValueChange={(next) => setDraft({ base: value, text: String(next) })}
      onValueCommit={commit}
      onValueCancel={() => setDraft(null)}
      renderValue={() => (
        <span className="flex items-center gap-1">
          <Input
            aria-label={t(`videoEditor.${label}`)}
            className="h-8 min-w-0 rounded-[var(--ui-radius-sm)] border-0 bg-transparent px-1 text-right tabular-nums [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none"
            style={{ width: `${Math.max(3, text.length + 1)}ch` }}
            type="number"
            value={text}
            min={min}
            max={max}
            step={step}
            disabled={disabled}
            onChange={(e) => setDraft({ base: value, text: e.target.value })}
            onBlur={commitInput}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                e.currentTarget.blur();
              } else if (e.key === "Escape") {
                e.preventDefault();
                e.stopPropagation();
                setDraft(null);
              }
            }}
          />
          {unit && <span className="text-inherit">{unit}</span>}
        </span>
      )}
    />
  );
}

import { useEffect, useRef } from "react";
import { useI18n } from "./video-editor-context";
import {
  audioGain,
  clipDuration,
  clipHidden,
  clipMuted,
  editDuration,
  outputSize,
} from "./timeline";
import { videoBounds } from "./preview-geometry";
import { drawEditText } from "./draw-text";
import type { VideoEditDocument } from "./types";

export function EditPreview({
  doc,
  time,
  playing,
  onTime,
  onStop,
  onError,
}: {
  doc: VideoEditDocument;
  time: number;
  playing: boolean;
  onTime: (time: number) => void;
  onStop: () => void;
  onError: () => void;
}) {
  const { t } = useI18n();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const latest = useRef({ doc, time, playing, onTime, onStop, onError });
  useEffect(() => {
    latest.current = { doc, time, playing, onTime, onStop, onError };
  }, [doc, time, playing, onTime, onStop, onError]);
  const first = doc.clips.find((c) => c.kind === "video");
  const size =
    first?.kind === "video"
      ? outputSize(first.source.width, first.source.height)
      : { width: 1920, height: 1080 };
  const mediaKey = JSON.stringify(
    doc.clips
      .flatMap((clip) =>
        clip.kind === "text"
          ? []
          : [{ id: clip.id, kind: clip.kind, url: clip.source.url }],
      )
      .sort((a, b) => a.id.localeCompare(b.id)),
  );
  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !ctx) return;
    let disposed = false;
    let failed = false;
    const fail = () => {
      if (disposed || failed) return;
      failed = true;
      latest.current.onStop();
      latest.current.onError();
    };
    const elements = new Map<string, HTMLMediaElement>();
    const prepared = new Set<string>();
    const pendingPlay = new Set<string>();
    const frameCallbacks = new Map<HTMLVideoElement, number>();
    let newVideoFrame = true;
    const watchFrames = (video: HTMLVideoElement) => {
      if (!video.requestVideoFrameCallback) return;
      frameCallbacks.set(
        video,
        video.requestVideoFrameCallback(() => {
          if (disposed) return;
          newVideoFrame = true;
          watchFrames(video);
        }),
      );
    };
    latest.current.doc.clips.forEach((clip) => {
      if (clip.kind === "text") return;
      const media = document.createElement(
        clip.kind === "video" ? "video" : "audio",
      );
      media.preload = "metadata";
      if (media instanceof HTMLVideoElement) media.playsInline = true;
      media.src = clip.source.url;
      media.onerror = fail;
      media.onloadeddata = media.onseeked = () => {
        newVideoFrame = true;
      };
      elements.set(clip.id, media);
      if (media instanceof HTMLVideoElement) watchFrames(media);
    });
    let current = latest.current.time;
    let lastReported = current;
    let lastReportAt = 0;
    let previousPlaying = false;
    let drawnDoc: VideoEditDocument | null = null;
    let drawnTime = -1;
    let drawnText = "";
    let frame = 0;
    const tick = (now: number) => {
      const state = latest.current;
      const doc = state.doc;
      const duration = editDuration(doc);
      if (
        (!state.playing && (!previousPlaying || state.time !== lastReported)) ||
        (state.playing && !previousPlaying)
      )
        current = state.time;
      if (state.playing && !previousPlaying) prepared.clear();
      const justPaused = previousPlaying && !state.playing;
      if (!state.playing && !justPaused) lastReported = state.time;
      previousPlaying = state.playing;
      const masterClip = doc.clips.find(
        (c) =>
          c.kind === "video" &&
          current >= c.start &&
          current < c.start + clipDuration(c),
      );
      const master = masterClip && elements.get(masterClip.id);
      // Native decoded media time is authoritative; never seek a playing video to a JS clock.
      if (
        state.playing &&
        masterClip?.kind === "video" &&
        master &&
        prepared.has(masterClip.id) &&
        !master.seeking
      ) {
        current =
          masterClip.start +
          Math.max(0, master.currentTime - masterClip.in) / masterClip.speed;
        if (master.ended) current = masterClip.start + clipDuration(masterClip);
        current = Math.min(duration, current);
        if (current >= duration) state.onStop();
      }
      const shouldReport =
        justPaused ||
        (state.playing && (now - lastReportAt >= 100 || current >= duration));
      if (shouldReport && current !== lastReported) {
        lastReported = current;
        lastReportAt = now;
        state.onTime(current);
      }
      const renderTime = Math.min(current, Math.max(0, duration - 1 / 30));
      const visibleText = doc.clips
        .filter(
          (c) =>
            c.kind === "text" &&
            renderTime >= c.start &&
            renderTime < c.start + c.duration,
        )
        .map((c) => c.id)
        .join("|");
      const draw =
        drawnText !== visibleText ||
        drawnDoc !== doc ||
        (!state.playing && drawnTime !== renderTime) ||
        newVideoFrame ||
        (state.playing &&
          master instanceof HTMLVideoElement &&
          !master.requestVideoFrameCallback);
      const videoClip = doc.clips.find(
        (clip) =>
          clip.kind === "video" &&
          renderTime >= clip.start &&
          renderTime < clip.start + clipDuration(clip),
      );
      const video = videoClip && elements.get(videoClip.id);
      const hidden = videoClip && clipHidden(doc, videoClip);
      // Keep the last complete composition until the requested video can be drawn.
      // Draw before starting the next seek, which can immediately drop readyState.
      if (
        draw &&
        (!videoClip ||
          hidden ||
          (video && video.readyState >= 2 && !video.seeking))
      ) {
        ctx.fillStyle = "black";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        if (
          videoClip?.kind === "video" &&
          video instanceof HTMLVideoElement &&
          !hidden
        ) {
          const bounds = videoBounds(videoClip, canvas.width, canvas.height);
          ctx.drawImage(video, bounds.x, bounds.y, bounds.width, bounds.height);
        }
        doc.clips.forEach((clip) => {
          if (
            clip.kind === "text" &&
            !clipHidden(doc, clip) &&
            renderTime >= clip.start &&
            renderTime < clip.start + clip.duration
          )
            drawEditText(ctx, clip, canvas.width, canvas.height);
        });
        drawnDoc = doc;
        drawnTime = renderTime;
        drawnText = visibleText;
        newVideoFrame = false;
      }
      doc.clips.forEach((clip) => {
        if (clip.kind === "text") return;
        const media = elements.get(clip.id)!;
        const visible =
          renderTime >= clip.start &&
          renderTime < clip.start + clipDuration(clip);
        if (!visible) {
          if (!media.paused) media.pause();
          prepared.delete(clip.id);
          // Only warm the upcoming clip, instead of downloading every source at once.
          if (
            clip.kind === "video" &&
            clip.start > current &&
            clip.start - current < 1
          )
            media.preload = "auto";
          return;
        }
        media.preload = "auto";
        const position = clip.in + (renderTime - clip.start) * clip.speed;
        if (media.readyState >= 1 && !media.seeking) {
          const entering = !prepared.has(clip.id);
          const syncAudio =
            clip.kind === "audio" &&
            Math.abs(media.currentTime - position) > 0.25;
          if (
            (entering || !state.playing || syncAudio) &&
            Math.abs(media.currentTime - position) > 0.015
          )
            media.currentTime = position;
          prepared.add(clip.id);
        }
        media.playbackRate = clip.speed;
        media.volume = clipMuted(doc, clip)
          ? 0
          : Math.max(0, Math.min(1, audioGain(clip, current)));
        const masterWaiting =
          !master || master.readyState < 2 || master.seeking || master.paused;
        const canPlay =
          state.playing &&
          current < duration &&
          media.readyState >= 2 &&
          !media.seeking &&
          !failed &&
          (clip.kind === "video" || !masterWaiting);
        if (canPlay && media.paused && !pendingPlay.has(clip.id)) {
          pendingPlay.add(clip.id);
          void media
            .play()
            .catch((error: unknown) => {
              if (
                !disposed &&
                !(error instanceof DOMException && error.name === "AbortError")
              )
                fail();
            })
            .finally(() => pendingPlay.delete(clip.id));
        }
        if (
          (!state.playing ||
            current >= duration ||
            (clip.kind === "audio" && masterWaiting)) &&
          !media.paused
        )
          media.pause();
      });
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      frameCallbacks.forEach((id, video) => video.cancelVideoFrameCallback(id));
      elements.forEach((media) => {
        media.pause();
        media.onerror = null;
        media.onloadeddata = media.onseeked = null;
        media.removeAttribute("src");
        media.load();
      });
    };
  }, [mediaKey]);
  return (
    <canvas
      ref={canvasRef}
      width={size.width}
      height={size.height}
      aria-label={t("videoEditor.preview")}
      className="edit-preview-canvas"
      style={{ aspectRatio: `${size.width}/${size.height}` }}
    />
  );
}

