import { useEffect, useMemo, useRef, useState } from "react";
import { useFrameCallback } from "./use-frame-callback";
import { Eye, EyeOff, Volume2, VolumeX } from "lucide-react";
import { useI18n, useVideoEditorServices } from "./video-editor-context";
import { createThumbnailCache } from "./thumbnail-cache";
import {
  clipDuration,
  editDuration,
  formatClock,
  timelineRows,
} from "./timeline";
import { EditIconButton } from "./edit-icon-button";
import { TimelineClip } from "./timeline-clip";
import type { VideoEditDocument } from "./types";

export function EditTimeline({
  doc,
  selected,
  time,
  disabled,
  playing,
  zoom,
  snapping,
  fitRevision,
  onZoom,
  onSelect,
  onSeek,
  onCommit,
}: {
  doc: VideoEditDocument;
  selected: string | null;
  time: number;
  disabled: boolean;
  playing: boolean;
  zoom: number;
  snapping: boolean;
  fitRevision: number;
  onZoom: (zoom: number) => void;
  onSelect: (id: string) => void;
  onSeek: (time: number) => void;
  onCommit: (doc: VideoEditDocument) => void;
}) {
  const { t } = useI18n();
  const scroller = useRef<HTMLDivElement>(null);
  const [viewport, setViewport] = useState(800);
  const [scrollLeft, setScrollLeft] = useState(0);
  const scroll = useFrameCallback(setScrollLeft);
  const { loadThumbnails } = useVideoEditorServices();
  const thumbnails = useMemo(
    () => (loadThumbnails ? createThumbnailCache(loadThumbnails) : null),
    [loadThumbnails],
  );
  useEffect(() => () => thumbnails?.dispose(), [thumbnails]);
  const visibleRange = useMemo(
    () => ({
      start: Math.max(0, scrollLeft - 192) / zoom,
      end: (scrollLeft + viewport + 192) / zoom,
    }),
    [scrollLeft, viewport, zoom],
  );
  const duration = editDuration(doc);
  const rows = useMemo(() => timelineRows(doc), [doc]);
  const length = Math.max(duration + 2, viewport / zoom);
  const lastFit = useRef(fitRevision);
  const videoCount = doc.clips.filter((clip) => clip.kind === "video").length;
  const previousVideoCount = useRef(0);
  useEffect(() => {
    const element = scroller.current;
    if (!element) return;
    const observer = new ResizeObserver(() =>
      setViewport(Math.max(1, element.clientWidth - 88)),
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  useEffect(() => {
    const addedVideo = videoCount > previousVideoCount.current;
    previousVideoCount.current = videoCount;
    if (addedVideo || fitRevision !== lastFit.current) {
      lastFit.current = fitRevision;
      onZoom(
        Math.max(1, Math.min(320, (viewport - 24) / Math.max(1, duration))),
      );
      if (scroller.current) scroller.current.scrollLeft = 0;
    }
  }, [fitRevision, videoCount, duration, viewport, onZoom]);
  useEffect(() => {
    const element = scroller.current;
    if (!element || !playing) return;
    const x = time * zoom;
    if (x > element.scrollLeft + viewport - 40 || x < element.scrollLeft)
      element.scrollLeft = Math.max(0, x - viewport * 0.2);
  }, [time, zoom, playing, viewport]);
  const step = [1, 2, 5, 10, 30, 60, 120].find((s) => s * zoom >= 90) ?? 300;
  const firstTick = Math.floor((visibleRange.start / step) * 10);
  const lastTick = Math.min(
    Math.ceil(length / step) * 10,
    Math.ceil((visibleRange.end / step) * 10),
  );
  const rowHeight = (kind: string) => {
    if (kind === "video") return 60;
    if (kind === "text") return 28;
    return 40;
  };
  const toggleTrack = (id: string, property: "hidden" | "muted") =>
    onCommit({
      ...doc,
      tracks: {
        ...doc.tracks,
        [id]: {
          ...doc.tracks?.[id],
          [property]: !doc.tracks?.[id]?.[property],
        },
      },
    });
  const seek = (x: number, element: HTMLElement) =>
    onSeek(
      Math.max(
        0,
        Math.min(duration, (x - element.getBoundingClientRect().left) / zoom),
      ),
    );
  const scrub = useFrameCallback(seek);
  return (
    <section
      ref={scroller}
      onScroll={(event) => scroll.schedule(event.currentTarget.scrollLeft)}
      className="relative min-h-0 flex-1 select-none overflow-auto"
      aria-label={t("videoEditor.timeline")}
    >
      <div
        className="grid min-h-full"
        style={{
          width: 88 + length * zoom,
          gridTemplateColumns: `88px ${length * zoom}px`,
          gridTemplateRows: `34px ${rows.map((r) => `${rowHeight(r.kind) + 4}px`).join(" ")} minmax(24px,1fr)`,
        }}
      >
        <div
          className="sticky left-0 z-10 bg-[var(--ui-bg-surface)]"
          style={{ gridColumn: 1, gridRow: 1 }}
        />
        <div
          style={{ gridColumn: 2, gridRow: 1 }}
          role="slider"
          tabIndex={0}
          aria-label={t("videoEditor.playhead")}
          aria-valuemin={0}
          aria-valuemax={duration}
          aria-valuenow={Math.min(time, duration)}
          className="relative touch-none outline-none focus-visible:ring-2 focus-visible:ring-[var(--ui-accent)]"
          onKeyDown={(e) => {
            if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
              e.preventDefault();
              onSeek(
                Math.max(
                  0,
                  Math.min(
                    duration,
                    time + (e.key === "ArrowLeft" ? -1 / 30 : 1 / 30),
                  ),
                ),
              );
            }
            if (e.key === "Home") onSeek(0);
            if (e.key === "End") onSeek(duration);
          }}
          onPointerDown={(e) => {
            if (e.button !== 0) return;
            e.preventDefault();
            e.currentTarget.focus({ preventScroll: true });
            scrub.cancel();
            e.currentTarget.setPointerCapture(e.pointerId);
            seek(e.clientX, e.currentTarget);
          }}
          onPointerMove={(e) => {
            if (e.currentTarget.hasPointerCapture(e.pointerId))
              scrub.schedule(e.clientX, e.currentTarget);
          }}
          onPointerUp={(e) => {
            if (!e.currentTarget.hasPointerCapture(e.pointerId)) return;
            scrub.cancel();
            seek(e.clientX, e.currentTarget);
            e.currentTarget.releasePointerCapture(e.pointerId);
          }}
          onPointerCancel={scrub.cancel}
          onLostPointerCapture={scrub.cancel}
        >
          {Array.from(
            { length: Math.max(0, lastTick - firstTick) },
            (_, index) => {
              const i = firstTick + index;
              return (
                <span
                  key={i}
                  className="pointer-events-none absolute top-1 border-l border-[var(--ui-border-strong)]"
                  style={{
                    left: (i * step * zoom) / 10,
                    height: i % 10 === 0 ? 12 : 5,
                  }}
                >
                  {i % 10 === 0 && (
                    <span className="absolute left-1 top-3 whitespace-nowrap tabular-nums text-[color:var(--ui-text-muted)]">
                      {formatClock((i * step) / 10)}
                    </span>
                  )}
                </span>
              );
            },
          )}
        </div>
        {rows.map((row, i) => (
          <div
            key={`controls-${row.id}`}
            className="sticky left-0 z-10 flex items-center justify-center gap-1 bg-[var(--ui-bg-surface)] pb-1"
            style={{ gridColumn: 1, gridRow: i + 2 }}
          >
            <EditIconButton
              label={doc.tracks?.[row.id]?.hidden ? "showTrack" : "hideTrack"}
              icon={doc.tracks?.[row.id]?.hidden ? EyeOff : Eye}
              disabled={disabled}
              onClick={() => toggleTrack(row.id, "hidden")}
            />
            <EditIconButton
              label={doc.tracks?.[row.id]?.muted ? "unmute" : "mute"}
              icon={doc.tracks?.[row.id]?.muted ? VolumeX : Volume2}
              disabled={disabled || row.kind === "text"}
              onClick={() => toggleTrack(row.id, "muted")}
            />
          </div>
        ))}
        {rows.map((row, i) => (
          <div
            key={row.id}
            className="relative mb-1"
            style={{
              gridColumn: 2,
              gridRow: i + 2,
              opacity: doc.tracks?.[row.id]?.hidden ? 0.35 : 1,
            }}
          >
            {row.clips
              .filter(
                (clip) =>
                  clip.id === selected ||
                  (clip.start <= visibleRange.end &&
                    clip.start + clipDuration(clip) >= visibleRange.start),
              )
              .map((clip) => (
                <TimelineClip
                  key={clip.id}
                  clip={clip}
                  visibleRange={visibleRange}
                  loadThumbnails={thumbnails?.load}
                  doc={doc}
                  selected={selected === clip.id}
                  zoom={zoom}
                  time={time}
                  snapping={snapping}
                  disabled={disabled}
                  onSelect={onSelect}
                  onCommit={onCommit}
                />
              ))}
          </div>
        ))}
        <div
          className="pointer-events-none relative"
          style={{ gridColumn: 2, gridRow: `1 / ${rows.length + 3}` }}
        >
          <div
            className="absolute inset-y-0 w-px bg-[var(--ui-text-primary)]"
            style={{ left: time * zoom }}
          >
            <span className="absolute -left-1.5 top-0 h-3.5 w-3 rounded-[var(--ui-radius-xs)] bg-[var(--ui-text-primary)]" />
          </div>
        </div>
      </div>
    </section>
  );
}

import { ClipSplitIcon } from "./internal/components/icons/glyphs/clip-split-icon";
import { ClipTrimBeforeIcon } from "./internal/components/icons/glyphs/clip-trim-before-icon";
import { ClipTrimAfterIcon } from "./internal/components/icons/glyphs/clip-trim-after-icon";
import {
  Pause,
  Play,
  Redo2,
  Type,
  Captions,
  Undo2,
  Magnet,
  ZoomIn,
  ZoomOut,
  Shrink,
  Scan,
} from "lucide-react";
import { BubbleSlider } from "./internal/components/ui/range-slider-bubble";
import { Button } from "./internal/components/ui/button";
import { useI18n } from "./video-editor-context";
import {
  clipDuration,
  editDuration,
  formatClock,
  splitClip,
  trimToPlayhead,
} from "./timeline";
import { EditIconButton } from "./edit-icon-button";
import { isSubtitle, MAX_SUBTITLES } from "./subtitles";
import type { useVideoEditor } from "./use-video-editor";

export function EditTransport({
  session,
  zoom,
  snapping,
  togglePlay,
  onAddText,
  onSubtitles,
  subtitlesOpen,
  onZoom,
  onSnap,
  onFit,
  onFullscreen,
}: {
  session: ReturnType<typeof useVideoEditor>;
  zoom: number;
  snapping: boolean;
  togglePlay: () => void;
  onAddText: () => void;
  onSubtitles: () => void;
  subtitlesOpen: boolean;
  onZoom: (zoom: number) => void;
  onSnap: () => void;
  onFit: () => void;
  onFullscreen: () => void;
}) {
  const { t } = useI18n();
  const { doc, time, playing, selected, busy } = session;
  const duration = editDuration(doc);
  const clip = doc.clips.find((c) => c.id === selected);
  const disabled = Boolean(busy) || session.readOnly;
  const outside =
    !clip ||
    time - clip.start < 0.1 ||
    clip.start + clipDuration(clip) - time < 0.1;
  return (
    <div className="grid shrink-0 grid-cols-1 items-center gap-1 border-b border-[var(--ui-border-subtle)] px-3 py-2 md:grid-cols-[1fr_auto_1fr]">
      <div className="flex items-center gap-1 overflow-x-auto">
        <EditIconButton
          label="undo"
          icon={Undo2}
          disabled={disabled || !session.canUndo}
          onClick={session.undo}
        />
        <EditIconButton
          label="redo"
          icon={Redo2}
          disabled={disabled || !session.canRedo}
          onClick={session.redo}
        />
        <EditIconButton
          label="split"
          icon={ClipSplitIcon}
          disabled={disabled || outside}
          onClick={() =>
            selected &&
            session.commit(splitClip(doc, selected, time, crypto.randomUUID()))
          }
        />
        <EditIconButton
          label="trimBefore"
          icon={ClipTrimBeforeIcon}
          disabled={disabled || outside}
          onClick={() =>
            selected &&
            session.commit(trimToPlayhead(doc, selected, time, "in"))
          }
        />
        <EditIconButton
          label="trimAfter"
          icon={ClipTrimAfterIcon}
          disabled={disabled || outside}
          onClick={() =>
            selected &&
            session.commit(trimToPlayhead(doc, selected, time, "out"))
          }
        />
        <EditIconButton
          label="addText"
          icon={Type}
          active={clip?.kind === "text" && clip.textType !== "subtitle"}
          disabled={disabled || !duration}
          onClick={onAddText}
        />
        <EditIconButton
          label="subtitles"
          icon={Captions}
          active={subtitlesOpen}
          disabled={
            disabled ||
            !duration ||
            doc.clips.filter(isSubtitle).length >= MAX_SUBTITLES
          }
          onClick={onSubtitles}
        />
      </div>
      <div className="flex items-center justify-center gap-2 text-sm tabular-nums">
        <span>{formatClock(time)}</span>
        <Button
          variant="ghost"
          size="icon"
          aria-label={t(playing ? "videoEditor.pause" : "videoEditor.play")}
          disabled={disabled || !duration || session.missing}
          onClick={togglePlay}
          className="size-8 rounded-full bg-[var(--ui-bg-control-active)] text-[color:var(--ui-text-primary)] hover:bg-[var(--ui-bg-control-hover)]"
        >
          {playing ? (
            <Pause className="size-4 fill-current" />
          ) : (
            <Play className="size-4 fill-current" />
          )}
        </Button>
        <span className="text-[color:var(--ui-text-muted)]">{formatClock(duration)}</span>
        <EditIconButton label="fullscreen" icon={Scan} onClick={onFullscreen} />
      </div>
      <div className="flex items-center justify-end gap-1">
        <EditIconButton
          label="snapping"
          icon={Magnet}
          active={snapping}
          onClick={onSnap}
        />
        <EditIconButton
          label="zoomOut"
          icon={ZoomOut}
          disabled={zoom <= 1}
          onClick={() => onZoom(Math.max(1, zoom / 1.4))}
        />
        <BubbleSlider
          aria-label={t("videoEditor.zoom")}
          size="sm"
          className="w-20"
          min={0}
          max={100}
          format={(value) =>
            `${Math.round((320 ** (value / 100) / 80) * 100)}%`
          }
          value={(Math.log(zoom) / Math.log(320)) * 100}
          onValueChange={(value) => onZoom(320 ** (value / 100))}
        />
        <EditIconButton
          label="zoomIn"
          icon={ZoomIn}
          disabled={zoom >= 320}
          onClick={() => onZoom(Math.min(320, zoom * 1.4))}
        />
        <EditIconButton label="fitTimeline" icon={Shrink} onClick={onFit} />
      </div>
    </div>
  );
}

