}

type TooltipLabelProps = {
  children: ReactElement;
  content: ReactNode;
  side?: ComponentProps<typeof TooltipPrimitive.Content>["side"];
  className?: string;
  disabled?: boolean;
};

export function TooltipLabel({
  children,
  content,
  side = "top",
  className,
  disabled = false,
}: TooltipLabelProps) {
  return (
    <Tooltip>
