"use client";

import {
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useRef,
  useState,
} from "react";
import { capturePointer, releasePointer } from "../touch";

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));

/** Nearest legal value on [min, max] for the given step. max counts as a
 * candidate when the step does not divide the range, so a pointer near the end
 * does not snap back onto the last whole step. */
export function snapSliderValue(
  next: number,
  min: number,
  max: number,
  step: number,
): number {
  // Neither case has a grid to walk. An empty range has exactly one legal
  // point, and a non-positive step only needs a clamp, which also keeps the
  // division below away from zero.
  if (!(max > min)) return min;
  if (!(step > 0)) return clamp(next, min, max);
  const whole = Math.floor(Number(((max - min) / step).toFixed(6)));
  const lastWhole = Number((min + whole * step).toFixed(6));
  const toGrid = clamp(
    Math.round((next - min) / step) * step + min,
    min,
    lastWhole,
  );
  const snapped =
    lastWhole < max && Math.abs(next - max) <= Math.abs(next - toGrid)
      ? max
      : toGrid;
  return Number(snapped.toFixed(6));
}

export interface SliderOptions {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** One committed edit after a pointer gesture or keyboard step. */
  onValueCommit?: (value: number) => void;
  onValueCancel?: () => void;
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  "aria-label"?: string;
  /** Announced instead of the raw number — pass one when the value carries a
   * unit or a suffix ("72.5 kg", "35%"); a bare number needs no valueText. */
  formatValueText?: (value: number) => string;
}

/**
 * Shared value + input plumbing for slider designs: controlled/uncontrolled
 * value, step snapping, pointer-capture drag along a track and arrow-key
 * control. Visuals and motion live in the component; this only owns the number.
 */
export function useSlider({
  value,
  defaultValue = 0,
  onValueChange,
  onValueCommit,
  onValueCancel,
  min = 0,
  max = 100,
  step = 1,
  disabled = false,
  "aria-label": ariaLabel,
  formatValueText,
}: SliderOptions) {
  const trackRef = useRef<HTMLDivElement>(null);
  const sliderEl = useRef<HTMLElement | null>(null);
  // The state drives visuals. Move reads this ref instead, so the first
  // pointermove after pointerdown does not have to wait on a re-render.
  const draggingRef = useRef<number | null>(null);
  const pending = useRef(defaultValue);
  const [internal, setInternal] = useState(defaultValue);
  const [dragging, setDragging] = useState(false);
  const controlled = value !== undefined;
  // Collapse inverted or empty ranges and non-positive steps here, so that
  // percent, ticks and the keyboard maths never divide by zero or walk a
  // NaN grid.
  const lo = min;
  const hi = max > min ? max : min;
  const stride = step > 0 ? step : 1;
  const current = clamp(controlled ? value : internal, lo, hi);
  const percent = hi > lo ? ((current - lo) / (hi - lo)) * 100 : 0;

  const commit = useCallback(
    (next: number) => {
      const clean = snapSliderValue(next, lo, hi, stride);
      pending.current = clean;
      if (!controlled) setInternal(clean);
      onValueChange?.(clean);
    },
    [controlled, onValueChange, lo, hi, stride],
  );

  const commitFromX = useCallback(
    (clientX: number) => {
      const rect = trackRef.current?.getBoundingClientRect();
      if (!rect || rect.width === 0) return;
      const ratio = clamp((clientX - rect.left) / rect.width, 0, 1);
      commit(lo + ratio * (hi - lo));
    },
    [commit, lo, hi],
  );

  const onPointerDown = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      if (disabled || event.button !== 0 || draggingRef.current !== null)
        return;
      event.preventDefault();
      // Start the drag first: capture is a convenience, and a browser that
      // refuses it — or a test DOM that has no pointer capture at all — must
      // not take the drag down with it.
      draggingRef.current = event.pointerId;
      setDragging(true);
      capturePointer(event.currentTarget, event.pointerId);
      // A click on the track should land keyboard focus on the handle.
      sliderEl.current?.focus({ preventScroll: true });
      commitFromX(event.clientX);
    },
    [disabled, commitFromX],
  );

  const onPointerMove = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      if (draggingRef.current !== event.pointerId || disabled) return;
      commitFromX(event.clientX);
    },
    [disabled, commitFromX],
  );

  const endDrag = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      if (draggingRef.current !== event.pointerId) return;
      draggingRef.current = null;
      setDragging(false);
      if (event.type === "pointerup" && !disabled) {
        commitFromX(event.clientX);
        onValueCommit?.(pending.current);
      } else onValueCancel?.();
      releasePointer(event.currentTarget, event.pointerId);
    },
    [disabled, commitFromX, onValueCommit, onValueCancel],
  );

  const onKeyDown = useCallback(
    (event: KeyboardEvent<HTMLElement>) => {
      if (disabled) return;
      const map: Record<string, number> = {
        ArrowRight: current + stride,
        ArrowUp: current + stride,
        ArrowLeft: current - stride,
        ArrowDown: current - stride,
        PageUp: current + stride * 10,
        PageDown: current - stride * 10,
        Home: lo,
        End: hi,
      };
      if (event.key in map) {
        event.preventDefault();
        commit(map[event.key]);
        onValueCommit?.(pending.current);
      }
    },
    [disabled, current, stride, lo, hi, commit, onValueCommit],
  );

  return {
    current,
    percent,
    dragging,
    min: lo,
    max: hi,
    step: stride,
    commit,
    /** Pointer handlers for the track element — drag anywhere on it. */
    trackProps: {
      ref: trackRef,
      onPointerDown,
      onPointerMove,
      onPointerUp: endDrag,
      onPointerCancel: endDrag,
      onLostPointerCapture: endDrag,
    },
    /** ARIA + keyboard props for the focusable slider element. */
    sliderProps: {
      // Callback keeps the handle typed across button/div/motion hosts.
      ref: (node: HTMLElement | null) => {
        sliderEl.current = node;
      },
      role: "slider" as const,
      tabIndex: disabled ? -1 : 0,
      "aria-label": ariaLabel,
      "aria-valuemin": lo,
      "aria-valuemax": hi,
      "aria-valuenow": current,
      "aria-valuetext": formatValueText?.(current),
      "aria-disabled": disabled || undefined,
      onKeyDown,
    },
  };
}

// Adapted from beUI (MIT); see docs/licenses/beui-MIT.txt.
export const TOUCH_GESTURE_CLASS = "select-none [-webkit-touch-callout:none]";

/**
 * The same opt-out for a gesture surface that wraps content the consumer owns:
 * a scroller, a context-menu trigger, a sheet header, a list row. Selection is
 * suppressed only where the platform runs its own press gestures — a coarse
 * pointer — so a mouse user can still select and copy that content. If the
 * gesture itself would paint a selection under the cursor, add `select-none`
 * for the duration of the gesture rather than reaching for
 * `TOUCH_GESTURE_CLASS`.
 *
 * `pointer: coarse` describes the *primary* pointer and nothing else, so a
 * hybrid machine reads it wrong in both directions: a tablet with a mouse
 * plugged in keeps touch as primary and loses mouse selection, and a laptop
 * with a touchscreen keeps the mouse as primary and leaves selection live
 * under a finger. No media query can answer per interaction — the query is
 * about the device, and the question is about the gesture in progress. The
 * default stays here because it is right on the machines that are one thing or
 * the other, and losing a selection is a nuisance; where the miss costs a
 * *gesture* instead, the surface pairs it with `holdSelection` on the press.
 */
export const TOUCH_GESTURE_CONTENT_CLASS =
  "[-webkit-touch-callout:none] pointer-coarse:select-none";

/**
 * Suppress selection on `element` for as long as a gesture is running on it,
 * whatever the primary pointer of the machine happens to be. Returns the
 * release. Inline, so it wins over the class above and is gone again the
 * moment the gesture ends.
 *
 * For the press gestures a native selection would otherwise steal — a
 * long-press that opens a menu. Elsewhere prefer the classes: a surface that
 * takes selection away for the whole session is a surface whose text nobody
 * can copy.
 */
export function holdSelection(element: HTMLElement) {
  element.style.setProperty("user-select", "none");
  element.style.setProperty("-webkit-user-select", "none");
  return () => {
    element.style.removeProperty("user-select");
    element.style.removeProperty("-webkit-user-select");
  };
}

/**
 * Pointer capture, best effort. WebKit throws `NotFoundError` when the pointer
 * is already gone by the time the handler runs — routine on iOS, where the
 * system can claim the touch first — and an uncaught throw takes the rest of
 * the handler, the gesture included, down with it. Touch pointers carry
 * implicit capture anyway, so losing it is never fatal.
 */
export function capturePointer(element: Element, pointerId: number) {
  try {
    element.setPointerCapture(pointerId);
  } catch {
    // Pointer is no longer active — implicit capture still applies on touch.
  }
}

/** Release a capture taken with `capturePointer`, ignoring a stale pointer. */
export function releasePointer(element: Element, pointerId: number) {
  try {
    if (element.hasPointerCapture(pointerId)) {
      element.releasePointerCapture(pointerId);
    }
  } catch {
    // Capture was already dropped by the browser.
  }
}

/**
 * Whether this event came from a pointer that is *hovering*: not a touch, and
 * not currently pressed. Which input the user is holding right now is not
 * something a device capability can answer — a touchscreen laptop hovers and
 * taps, and iPadOS reports a fine hovering pointer for a finger — so both
 * paths stay live and each handler branches on the event it was given.
 *
 * A pen resting on the glass is making contact, not hovering: `buttons` is the
 * tell, and it sends a pen tap down the same route a finger takes.
 *
 * This answers what an *enter* asks. A leave is the other half of a pair and
 * has to be read against the enter that started it — `useHoverGesture` in
 * `lib/hooks/use-hover-gesture` does that, and hover surfaces should use it
 * rather than asking this question twice.
 */
export const isHoveringPointer = (event: {
  pointerType: string;
  buttons: number;
}) => event.pointerType !== "touch" && event.buttons === 0;

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type { EditSource } from "./types";
export function loadEditSource(
  source: Pick<EditSource, "id" | "url" | "label" | "kind">,
  signal: AbortSignal,
): Promise<EditSource> {
  return new Promise((resolve, reject) => {
    const media = document.createElement(
      source.kind === "video" ? "video" : "audio",
    );
    const cleanup = () => {
      clearTimeout(timer);
      signal.removeEventListener("abort", abort);
      media.onloadedmetadata = null;
      media.onerror = null;
      media.removeAttribute("src");
      media.load();
    };
    const fail = (error: Error) => {
      cleanup();
      reject(error);
    };
    const abort = () => fail(new DOMException("Aborted", "AbortError"));
    const timer = setTimeout(
      () => fail(new Error("Media metadata timed out")),
      30000,
    );
    media.onloadedmetadata = () => {
      if (!Number.isFinite(media.duration) || media.duration <= 0)
        return fail(new Error("Invalid duration"));
      const result = {
        ...source,
        duration: media.duration,
        width: 1920,
        height: 1080,
      };
      if (media instanceof HTMLVideoElement) {
        result.width = media.videoWidth;
        result.height = media.videoHeight;
      }
      cleanup();
      resolve(result);
    };
    media.onerror = () => fail(new Error("Unable to read media"));
    signal.addEventListener("abort", abort, { once: true });
    if (signal.aborted) return abort();
    media.preload = "metadata";
    media.src = source.url;
  });
}

import type { MediaClip } from "./types";

export function videoBounds(clip: MediaClip, width: number, height: number) {
  const transform = clip.transform ?? { x: 0.5, y: 0.5, scale: 1 };
  const fit = Math.min(width / clip.source.width, height / clip.source.height);
  const w = clip.source.width * fit * transform.scale;
  const h = clip.source.height * fit * transform.scale;
  return {
    x: transform.x * width - w / 2,
    y: transform.y * height - h / 2,
    width: w,
    height: h,
  };
}

import { useMemo, useRef } from "react";
import { useFrameCallback } from "./use-frame-callback";
import { Button } from "./internal/components/ui/button";
import { useI18n } from "./video-editor-context";
import { editTextBounds } from "./draw-text";
import { videoBounds } from "./preview-geometry";
import type { EditClip } from "./types";

export function PreviewSelection({
  clip,
  width,
  height,
  disabled,
  onDraft,
  onCommit,
  onStop,
}: {
  clip: EditClip;
  width: number;
  height: number;
  disabled: boolean;
  onDraft: (clip: EditClip | null) => void;
  onCommit: (clip: EditClip) => void;
  onStop: () => void;
}) {
  const { t } = useI18n();
  const drag = useRef<{
    x: number;
    y: number;
    clip: EditClip;
    mode: "move" | "scale";
  } | null>(null);
  const bounds = useMemo(() => {
    if (clip.kind === "audio") return { x: 0, y: 0, width: 0, height: 0 };
    return clip.kind === "text"
      ? editTextBounds(clip, width, height)
      : videoBounds(clip, width, height);
  }, [clip, width, height]);
  const changed = (x: number, y: number) => {
    const active = drag.current;
    if (!active) return clip;
    const dx = (x - active.x) / width;
    const dy = (y - active.y) / height;
    const original = active.clip;
    if (original.kind === "audio") return original;
    if (active.mode === "move") {
      if (original.kind === "text")
        return {
          ...original,
          x: Math.max(0, Math.min(1, original.x + dx)),
          y: Math.max(0, Math.min(1, original.y + dy)),
        };
      const transform = original.transform ?? { x: 0.5, y: 0.5, scale: 1 };
      return {
        ...original,
        transform: {
          ...transform,
          x: Math.max(0, Math.min(1, transform.x + dx)),
          y: Math.max(0, Math.min(1, transform.y + dy)),
        },
      };
    }
    const factor = Math.max(0.1, 1 + dx + dy);
    if (original.kind === "text")
      return {
        ...original,
        fontSize: Math.max(12, Math.min(200, original.fontSize * factor)),
      };
    const transform = original.transform ?? { x: 0.5, y: 0.5, scale: 1 };
    return {
      ...original,
      transform: {
        ...transform,
        scale: Math.max(0.1, Math.min(3, transform.scale * factor)),
      },
    };
  };
  const draft = useFrameCallback((x: number, y: number) => {
    if (drag.current) onDraft(changed(x, y));
  });
  if (clip.kind === "audio") return null;
  const events = (mode: "move" | "scale") => ({
    onPointerDown: (e: React.PointerEvent<HTMLButtonElement>) => {
      if (disabled || e.button !== 0) return;
      draft.cancel();
      e.preventDefault();
      e.currentTarget.focus({ preventScroll: true });
      e.stopPropagation();
      onStop();
      drag.current = { x: e.clientX, y: e.clientY, clip, mode };
      e.currentTarget.setPointerCapture(e.pointerId);
    },
    onPointerMove: (e: React.PointerEvent<HTMLButtonElement>) => {
      if (drag.current && e.currentTarget.hasPointerCapture(e.pointerId))
        draft.schedule(e.clientX, e.clientY);
    },
    onLostPointerCapture: () => {
      draft.cancel();
      drag.current = null;
      onDraft(null);
    },
    onPointerCancel: () => {
      draft.cancel();
      drag.current = null;
      onDraft(null);
    },
    onPointerUp: (e: React.PointerEvent<HTMLButtonElement>) => {
      if (!drag.current || !e.currentTarget.hasPointerCapture(e.pointerId))
        return;
      draft.cancel();
      const next = changed(e.clientX, e.clientY);
      drag.current = null;
      e.currentTarget.releasePointerCapture(e.pointerId);
      onDraft(null);
      onCommit(next);
    },
  });
  return (
    <div
      className="pointer-events-none absolute border border-[var(--ui-accent)]"
      style={{
        left: bounds.x,
        top: bounds.y,
        width: bounds.width,
        height: bounds.height,
      }}
    >
      <Button
        variant="ghost"
        aria-label={t("videoEditor.moveSelection")}
        disabled={disabled}
        className="pointer-events-auto absolute inset-0 h-full w-full cursor-move touch-none rounded-none p-0 hover:bg-transparent active:bg-transparent transition-none"
        {...events("move")}
        onKeyDown={(e) => {
          if (
            !["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(e.key)
          )
            return;
          e.preventDefault();
          const dx =
            Number(e.key === "ArrowRight") - Number(e.key === "ArrowLeft");
          const dy =
            Number(e.key === "ArrowDown") - Number(e.key === "ArrowUp");
          if (clip.kind === "text")
            onCommit({
              ...clip,
              x: Math.max(0, Math.min(1, clip.x + dx * 0.01)),
              y: Math.max(0, Math.min(1, clip.y + dy * 0.01)),
            });
          else {
            const transform = clip.transform ?? { x: 0.5, y: 0.5, scale: 1 };
            onCommit({
              ...clip,
              transform: {
                ...transform,
                x: Math.max(0, Math.min(1, transform.x + dx * 0.01)),
                y: Math.max(0, Math.min(1, transform.y + dy * 0.01)),
              },
            });
          }
        }}
      />
      <Button
        variant="ghost"
        aria-label={t("videoEditor.resizeSelection")}
        disabled={disabled}
        className="pointer-events-auto absolute -right-3 -bottom-3 size-6 cursor-nwse-resize touch-none p-0 hover:bg-transparent active:bg-transparent transition-none"
        {...events("scale")}
        onKeyDown={(e) => {
          if (e.key !== "ArrowUp" && e.key !== "ArrowDown") return;
          e.preventDefault();
          const step = e.key === "ArrowUp" ? 1 : -1;
          if (clip.kind === "text")
            onCommit({
              ...clip,
              fontSize: Math.max(12, Math.min(200, clip.fontSize + step)),
            });
          else {
            const transform = clip.transform ?? { x: 0.5, y: 0.5, scale: 1 };
            onCommit({
              ...clip,
              transform: {
                ...transform,
                scale: Math.max(
                  0.1,
                  Math.min(3, transform.scale + step * 0.05),
                ),
              },
            });
          }
        }}
      >
        <span className="size-2 rounded-[var(--ui-radius-xs)] border border-[var(--ui-text-primary)] bg-[var(--ui-accent)]" />
      </Button>
      <span className="absolute -left-1 -bottom-1 size-2 rounded-[var(--ui-radius-xs)] border border-[var(--ui-text-primary)] bg-[var(--ui-accent)]" />
    </div>
  );
}

import { useEffect, useRef, useState, type RefObject } from "react";
import { EditPreview } from "./edit-preview";
import { PreviewSelection } from "./preview-selection";
import { clipDuration, clipHidden, editDuration, outputSize } from "./timeline";
import type { EditClip, VideoEditDocument } from "./types";

export function PreviewStage({
  doc,
  selected,
  time,
  playing,
  disabled,
  stageRef,
  onTime,
  onStop,
  onError,
  onChange,
}: {
  doc: VideoEditDocument;
  selected: string | null;
  time: number;
  playing: boolean;
  disabled: boolean;
  stageRef: RefObject<HTMLDivElement | null>;
  onTime: (time: number) => void;
  onStop: () => void;
  onError: () => void;
  onChange: (clip: EditClip) => void;
}) {
  const container = useRef<HTMLDivElement>(null);
  const [available, setAvailable] = useState({ width: 1, height: 1 });
  const [draft, setDraft] = useState<EditClip | null>(null);
  const first = doc.clips.find((c) => c.kind === "video");
  const source =
    first?.kind === "video"
      ? outputSize(first.source.width, first.source.height)
      : { width: 1920, height: 1080 };
  useEffect(() => {
    const element = container.current;
    if (!element) return;
    const measure = () =>
      setAvailable({
        width: element.clientWidth,
        height: element.clientHeight,
      });
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    measure();
    return () => observer.disconnect();
  }, []);
  const scale = Math.min(
    available.width / source.width,
    available.height / source.height,
  );
  const width = Math.max(1, source.width * scale);
  const height = Math.max(1, source.height * scale);
  const clip = doc.clips.find((c) => c.id === selected);
  const activeDraft = draft && clip?.id === draft.id ? draft : null;
  const previewDoc = activeDraft
    ? {
        ...doc,
        clips: doc.clips.map((c) =>
          c.id === activeDraft.id ? activeDraft : c,
        ),
      }
    : doc;
  const showBounds =
    clip &&
    !clipHidden(doc, clip) &&
    time >= clip.start &&
    Math.min(time, editDuration(doc) - 1 / 30) <
      clip.start + clipDuration(clip);
  return (
    <div
      ref={stageRef}
      className="edit-preview-stage flex h-full min-h-0 min-w-0 flex-1 items-center justify-center p-2"
    >
      <div
        ref={container}
        className="flex h-full w-full min-w-0 items-center justify-center"
      >
        <div className="relative shrink-0" style={{ width, height }}>
          <EditPreview
            doc={previewDoc}
            time={time}
            playing={playing}
            onTime={onTime}
            onStop={onStop}
            onError={onError}
          />
          {showBounds && (
            <PreviewSelection
              clip={activeDraft ?? clip}
              width={width}
              height={height}
              disabled={disabled}
              onDraft={setDraft}
              onCommit={onChange}
              onStop={onStop}
            />
          )}
        </div>
      </div>
    </div>
  );
}

