import type { VideoEditorServices } from "./types";

type Entry = {
  controller: AbortController;
  promise: Promise<string[]>;
  users: number;
  ready: boolean;
};

/** One editor session owns the cache; consumers can cancel independently. */
export function createThumbnailCache(
  loader: NonNullable<VideoEditorServices["loadThumbnails"]>,
  maxEntries = 32,
) {
  const entries = new Map<string, Entry>();
  const load = (url: string, signal: AbortSignal): Promise<string[]> => {
    if (signal.aborted) return Promise.reject(signal.reason);
    let entry = entries.get(url);
    if (!entry) {
      const controller = new AbortController();
      const created: Entry = {
        controller,
        users: 0,
        ready: false,
        promise: Promise.resolve().then(() => {
          controller.signal.throwIfAborted();
          return loader(url, controller.signal);
        }),
      };
      entry = created;
      entries.set(url, created);
      created.promise = created.promise.then(
        (frames) => {
          controller.signal.throwIfAborted();
          created.ready = true;
          return frames;
        },
        (error: unknown) => {
          if (entries.get(url) === created) entries.delete(url);
          throw error;
        },
      );
    }
    const current = entry;
    entries.delete(url);
    entries.set(url, current);
    current.users++;
    return new Promise((resolve, reject) => {
      let finished = false;
      const finish = (complete: () => void) => {
        if (finished) return;
        finished = true;
        signal.removeEventListener("abort", abort);
        current.users--;
        for (const [key, cached] of entries) {
          if (entries.size <= maxEntries) break;
          if (cached.ready && cached.users === 0) entries.delete(key);
        }
        complete();
        queueMicrotask(() => {
          if (current.users === 0 && !current.ready) {
            current.controller.abort();
            if (entries.get(url) === current) entries.delete(url);
          }
        });
      };
      const abort = () => finish(() => reject(signal.reason));
      signal.addEventListener("abort", abort, { once: true });
      current.promise.then(
        (frames) => finish(() => resolve(frames)),
        (error: unknown) => finish(() => reject(error)),
      );
    });
  };
  return {
    load,
    dispose() {
      entries.forEach((entry) => entry.controller.abort());
      entries.clear();
    },
  };
}

import { ClipContextMenu } from "./clip-context-menu";
import { useRef, useState } from "react";
import { useFrameCallback } from "./use-frame-callback";
import { Button } from "./internal/components/ui/button";
import { useI18n } from "./video-editor-context";
import { cn } from "./internal/lib/utils";
import { VideoClipStrip } from "./video-clip-strip";
import { AudioClipWaveform } from "./audio-clip-waveform";
import {
  clipDuration,
  moveVideo,
  normalizeEdit,
  snapTime,
  trimClip,
} from "./timeline";
import type { EditClip, VideoEditDocument, VideoEditorServices } from "./types";
import { isSubtitle } from "./subtitles";

type Gesture = {
  x: number;
  mode: "move" | "in" | "out";
  doc: VideoEditDocument;
  points: number[];
};
export function TimelineClip({
  clip,
  visibleRange,
  loadThumbnails,
  doc,
  selected,
  zoom,
  time,
  snapping,
  disabled,
  onSelect,
  onCommit,
}: {
  clip: EditClip;
  visibleRange?: { start: number; end: number };
  loadThumbnails?: VideoEditorServices["loadThumbnails"];
  doc: VideoEditDocument;
  selected: boolean;
  zoom: number;
  time: number;
  snapping: boolean;
  disabled: boolean;
  onSelect: (id: string) => void;
  onCommit: (doc: VideoEditDocument) => void;
}) {
  const { t } = useI18n();
  const gesture = useRef<Gesture | null>(null);
  const [preview, setPreview] = useState<EditClip | null>(null);
  const displayed = preview ?? clip;
  const adjusted = (mode: Gesture["mode"], delta: number) => {
    const points = gesture.current?.points ?? [0, time];
    const start = clip.start;
    const end = start + clipDuration(clip);
    if (mode === "move") {
      let next = Math.max(0, start + delta);
      if (snapping && clip.kind !== "video") {
        const snappedStart = snapTime(next, points, 8 / zoom);
        const snappedEnd =
          snapTime(next + clipDuration(clip), points, 8 / zoom) -
          clipDuration(clip);
        next = snappedStart !== next ? snappedStart : Math.max(0, snappedEnd);
      }
      return { ...clip, start: next };
    }
    let edge = (mode === "in" ? start : end) + delta;
    if (snapping) edge = snapTime(edge, points, 8 / zoom);
    return trimClip(clip, mode, edge - (mode === "in" ? start : end));
  };
  const draft = useFrameCallback((x: number) => {
    const active = gesture.current;
    if (active) setPreview(adjusted(active.mode, (x - active.x) / zoom));
  });
  const events = (mode: Gesture["mode"]) => ({
    onPointerDown: (e: React.PointerEvent<HTMLButtonElement>) => {
      if (disabled || e.button !== 0) return;
      e.preventDefault();
      e.currentTarget.focus({ preventScroll: true });
      e.stopPropagation();
      draft.cancel();
      onSelect(clip.id);
      gesture.current = {
        x: e.clientX,
        mode,
        doc,
        points: [
          0,
          time,
          ...doc.clips
            .filter((item) => item.id !== clip.id)
            .flatMap((item) => [item.start, item.start + clipDuration(item)]),
        ],
      };
      e.currentTarget.setPointerCapture(e.pointerId);
    },
    onPointerMove: (e: React.PointerEvent<HTMLButtonElement>) => {
      const active = gesture.current;
      if (active && e.currentTarget.hasPointerCapture(e.pointerId))
        draft.schedule(e.clientX);
    },
    onLostPointerCapture: () => {
      draft.cancel();
      gesture.current = null;
      setPreview(null);
    },
    onPointerCancel: () => {
      draft.cancel();
      gesture.current = null;
      setPreview(null);
    },
    onPointerUp: (e: React.PointerEvent<HTMLButtonElement>) => {
      const active = gesture.current;
      if (!active || !e.currentTarget.hasPointerCapture(e.pointerId)) return;
      draft.cancel();
      const next = adjusted(active.mode, (e.clientX - active.x) / zoom);
      e.currentTarget.releasePointerCapture(e.pointerId);
      gesture.current = null;
      setPreview(null);
      if (active.doc !== doc || Math.abs(e.clientX - active.x) < 2) return;
      if (clip.kind === "video" && active.mode === "move") {
        const videos = doc.clips.filter(
          (c) => c.kind === "video" && c.id !== clip.id,
        );
        const at = videos.findIndex(
          (c) => next.start < c.start + clipDuration(c) / 2,
        );
        videos.splice(at < 0 ? videos.length : at, 0, clip);
        onCommit(
          normalizeEdit({
            ...doc,
            clips: [...videos, ...doc.clips.filter((c) => c.kind !== "video")],
          }),
        );
      } else
        onCommit(
          normalizeEdit({
            ...doc,
            clips: doc.clips.map((c) => (c.id === clip.id ? next : c)),
          }),
        );
    },
  });
  const width = Math.max(6, clipDuration(displayed) * zoom);
  return (
    <ClipContextMenu
      clip={clip}
      doc={doc}
      time={time}
      disabled={disabled}
      onCommit={onCommit}
      onSelect={onSelect}
    >
      <div
        className={cn(
          "edit-clip absolute inset-y-0",
          `edit-clip-${clip.kind}`,
          isSubtitle(clip) && "edit-clip-subtitle",
          selected && "edit-clip-selected",
        )}
        style={{ left: displayed.start * zoom, width }}
      >
        <Button
          variant="ghost"
          aria-label={clip.kind === "text" ? clip.text : clip.source.label}
          aria-pressed={selected}
          disabled={disabled}
          className="relative h-full w-full touch-none overflow-hidden rounded-none p-0 hover:bg-transparent active:bg-transparent transition-none"
          {...events("move")}
          onClick={() => onSelect(clip.id)}
          onKeyDown={(e) => {
            if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
            e.preventDefault();
            const direction = e.key === "ArrowLeft" ? -1 : 1;
            if (clip.kind === "video")
              onCommit(moveVideo(doc, clip.id, direction));
            else
              onCommit({
                ...doc,
                clips: doc.clips.map((c) =>
                  c.id === clip.id
                    ? { ...c, start: Math.max(0, c.start + direction * 0.1) }
                    : c,
                ),
              });
          }}
        >
          {clip.kind === "video" && (
            <VideoClipStrip
              clip={displayed as typeof clip}
              width={width}
              loadThumbnails={loadThumbnails}
              visibleFrom={
                visibleRange ? (visibleRange.start - displayed.start) * zoom : 0
              }
              visibleTo={
                visibleRange
                  ? (visibleRange.end - displayed.start) * zoom
                  : width
              }
            />
          )}
          {clip.kind === "audio" && (
            <AudioClipWaveform clip={displayed as typeof clip} />
          )}
          {clip.kind === "text" && (
            <span className="truncate px-3 text-[color:var(--ui-text-secondary)]">
              {clip.text}
            </span>
          )}
        </Button>
        {selected &&
          (["in", "out"] as const).map((edge) => (
            <Button
              key={edge}
              variant="ghost"
              disabled={disabled}
              aria-label={t(
                edge === "in"
                  ? "videoEditor.trimStartHandle"
                  : "videoEditor.trimEndHandle",
              )}
              className={cn(
                "edit-trim-handle absolute inset-y-0 h-full w-6 touch-none rounded-none p-0 active:bg-transparent transition-none",
                edge === "in"
                  ? "-left-2 cursor-ew-resize"
                  : "-right-2 cursor-ew-resize",
              )}
              {...events(edge)}
              onKeyDown={(e) => {
                if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
                e.preventDefault();
                const next = trimClip(
                  clip,
                  edge,
                  e.key === "ArrowLeft" ? -0.1 : 0.1,
                );
                onCommit(
                  normalizeEdit({
                    ...doc,
                    clips: doc.clips.map((c) => (c.id === clip.id ? next : c)),
                  }),
                );
              }}
            >
              <span className="h-1/3 w-0.5 rounded-full bg-[var(--ui-text-primary)]" />
            </Button>
          ))}
      </div>
    </ClipContextMenu>
  );
}

import type { EditClip, VideoEditDocument } from "./types";
import { isSubtitle, MAX_SUBTITLES, subtitleTrackId } from "./subtitles";
import { audioEnvelope } from "./audio-envelope";

export const EMPTY_EDIT: VideoEditDocument = { version: 1, clips: [] };
export const MIN_CLIP_DURATION = 0.1;
export function clipDuration(clip: EditClip) {
  return clip.kind === "text"
    ? clip.duration
    : (clip.out - clip.in) / clip.speed;
}
export function normalizeEdit(doc: VideoEditDocument): VideoEditDocument {
  let cursor = 0;
  const clips = doc.clips.map((clip) => {
    if (clip.kind !== "video") return clip;
    const next = { ...clip, start: cursor };
    cursor += clipDuration(clip);
    return next;
  });
  return { ...doc, clips };
}
export function editDuration(doc: VideoEditDocument) {
  // The main video track defines the output length. Audio/text are clipped at its end.
  return doc.clips
    .filter((c) => c.kind === "video")
    .reduce((sum, c) => sum + clipDuration(c), 0);
}
export function splitClip(
  doc: VideoEditDocument,
  id: string,
  time: number,
  newId: string,
) {
  const clip = doc.clips.find((c) => c.id === id);
  if (!clip) return doc;
  if (isSubtitle(clip) && doc.clips.filter(isSubtitle).length >= MAX_SUBTITLES)
    return doc;
  const offset = time - clip.start;
  const duration = clipDuration(clip);
  if (offset < MIN_CLIP_DURATION || duration - offset < MIN_CLIP_DURATION)
    return doc;
  let left: EditClip;
  let right: EditClip;
  if (clip.kind === "text") {
    left = { ...clip, trackId: trackId(clip), duration: offset };
    right = {
      ...clip,
      trackId: trackId(clip),
      id: newId,
      start: time,
      duration: duration - offset,
    };
  } else {
    const cut = clip.in + offset * clip.speed;
    const fadeRange = clip.fadeRange ?? {
      in: clip.in,
      out: clip.out,
      speed: clip.speed,
    };
    left = { ...clip, trackId: trackId(clip), out: cut, fadeRange };
    right = {
      ...clip,
      trackId: trackId(clip),
      id: newId,
      start: time,
      in: cut,
      fadeRange,
    };
  }
  return normalizeEdit({
    ...doc,
    clips: doc.clips.flatMap((c) => (c.id === id ? [left, right] : [c])),
  });
}
export function moveVideo(
  doc: VideoEditDocument,
  id: string,
  direction: -1 | 1,
) {
  const clips = [...doc.clips];
  const indexes = clips.flatMap((c, i) => (c.kind === "video" ? [i] : []));
  const from = indexes.findIndex((i) => clips[i].id === id);
  const to = from + direction;
  if (from < 0 || to < 0 || to >= indexes.length) return doc;
  [clips[indexes[from]], clips[indexes[to]]] = [
    clips[indexes[to]],
    clips[indexes[from]],
  ];
  return normalizeEdit({ ...doc, clips });
}
export function duplicateClip(
  doc: VideoEditDocument,
  id: string,
  newId: string,
) {
  const index = doc.clips.findIndex((clip) => clip.id === id);
  if (index < 0) return doc;
  const clip = doc.clips[index];
  if (isSubtitle(clip) && doc.clips.filter(isSubtitle).length >= MAX_SUBTITLES)
    return doc;
  const clips = [...doc.clips];
  clips.splice(index + 1, 0, {
    ...clip,
    id: newId,
    start: clip.start + clipDuration(clip),
  });
  return normalizeEdit({ ...doc, clips });
}
export function audioGain(
  clip: Exclude<EditClip, { kind: "text" }>,
  time: number,
) {
  if (clip.muted) return 0;
  const offset = time - clip.start;
  const remaining = clipDuration(clip) - offset;
  if (offset < 0 || remaining <= 0) return 0;
  const envelope = audioEnvelope(clip);
  const position = envelope.offset + offset * envelope.rate;
  const { fadeIn, fadeOut } = envelope;
  return (
    clip.volume *
    Math.max(0, Math.min(1, fadeIn > 0 ? position / fadeIn : 1)) *
    Math.max(
      0,
      Math.min(1, fadeOut > 0 ? (envelope.duration - position) / fadeOut : 1),
    )
  );
}
export function outputSize(
  width: number,
  height: number,
  resolution: 480 | 720 | 1080 = 1080,
) {
  const ratio = Math.min(1, (resolution * 16) / 9 / width, resolution / height);
  return {
    width: Math.max(2, Math.floor((width * ratio) / 2) * 2),
    height: Math.max(2, Math.floor((height * ratio) / 2) * 2),
  };
}
export function formatTime(time: number) {
  const value = Math.max(0, time);
  return `${Math.floor(value / 60)
    .toString()
    .padStart(2, "0")}:${(value % 60).toFixed(1).padStart(4, "0")}`;
}

export function trackId(clip: EditClip) {
  if (clip.kind === "video") return "video";
  if (clip.kind === "text" && clip.textType === "subtitle")
    return subtitleTrackId(clip);
  return clip.trackId ?? clip.id;
}
export function clipHidden(doc: VideoEditDocument, clip: EditClip) {
  return Boolean(doc.tracks?.[trackId(clip)]?.hidden);
}
export function clipMuted(doc: VideoEditDocument, clip: EditClip) {
  return Boolean(
    doc.tracks?.[trackId(clip)]?.muted ||
    (clip.kind !== "text" && clip.muted) ||
    (clip.kind === "audio" && clipHidden(doc, clip)),
  );
}
export function timelineRows(doc: VideoEditDocument) {
  const groups = new Map<string, EditClip[]>();
  groups.set("video", []);
  for (const clip of doc.clips) {
    const id = trackId(clip);
    const group = groups.get(id);
    if (group) group.push(clip);
    else groups.set(id, [clip]);
  }
  const rows = [...groups].map(([id, clips]) => ({
    id,
    clips,
    kind: clips[0]?.kind ?? "video",
  }));
  const rank = { text: 0, video: 1, audio: 2 };
  return rows.sort((a, b) => rank[a.kind] - rank[b.kind]);
}
export function trimClip(
  clip: EditClip,
  edge: "in" | "out",
  delta: number,
): EditClip {
  const duration = clipDuration(clip);
  if (edge === "in") {
    let amount = Math.min(duration - MIN_CLIP_DURATION, delta);
    if (clip.kind === "text") {
      amount = Math.max(-clip.start, amount);
      return {
        ...clip,
        start: clip.start + amount,
        duration: duration - amount,
      };
    }
    amount = Math.max(-clip.in / clip.speed, amount);
    if (clip.kind === "audio") amount = Math.max(-clip.start, amount);
    return {
      ...clip,
      in: clip.in + amount * clip.speed,
      start: clip.kind === "video" ? clip.start : clip.start + amount,
    };
  }
  if (clip.kind === "text")
    return { ...clip, duration: Math.max(MIN_CLIP_DURATION, duration + delta) };
  return {
    ...clip,
    out: Math.min(
      clip.source.duration,
      Math.max(
        clip.in + MIN_CLIP_DURATION * clip.speed,
        clip.out + delta * clip.speed,
      ),
    ),
  };
}
export function trimToPlayhead(
  doc: VideoEditDocument,
  id: string,
  time: number,
  edge: "in" | "out",
) {
  const clip = doc.clips.find((c) => c.id === id);
  if (!clip || time <= clip.start || time >= clip.start + clipDuration(clip))
    return doc;
  const delta =
    edge === "in" ? time - clip.start : time - clip.start - clipDuration(clip);
  return normalizeEdit({
    ...doc,
    clips: doc.clips.map((c) => (c.id === id ? trimClip(c, edge, delta) : c)),
  });
}
export function snapTime(value: number, points: number[], threshold: number) {
  let result = value;
  let distance = threshold;
  for (const point of points) {
    const next = Math.abs(value - point);
    if (next < distance) {
      distance = next;
      result = point;
    }
  }
  return Math.max(0, result);
}
export function formatClock(time: number) {
  const seconds = Math.max(0, Math.floor(time));
  return `${Math.floor(seconds / 60)
    .toString()
    .padStart(2, "0")}:${(seconds % 60).toString().padStart(2, "0")}`;
}

export type EditSource = {
  id: string;
  url: string;
  label: string;
  kind: "video" | "audio";
  duration: number;
  width: number;
  height: number;
};

export type MediaClip = {
  id: string;
  kind: "video" | "audio";
  source: EditSource;
  trackId?: string;
  transform?: { x: number; y: number; scale: number };
  start: number;
  in: number;
  out: number;
  speed: number;
  volume: number;
  muted: boolean;
  fadeIn: number;
  fadeOut: number;
  /** Original source interval used to preserve fades across cuts. */
  fadeRange?: { in: number; out: number; speed: number };
};

export type TextClip = {
  id: string;
  kind: "text";
  textType?: "subtitle";
  start: number;
  duration: number;
  text: string;
  trackId?: string;
  bold?: boolean;
  italic?: boolean;
  align?: "left" | "center" | "right";
  fontSize: number;
  color: string;
  x: number;
  y: number;
};

export type SubtitleClip = TextClip & { textType: "subtitle" };

export type EditClip = MediaClip | TextClip;
export type VideoEditDocument = {
  version: 1;
  importedSources?: string[];
  clips: EditClip[];
  tracks?: Record<string, { hidden?: boolean; muted?: boolean }>;
};

export type VideoEditorSource = Pick<
  EditSource,
  "id" | "url" | "label" | "kind"
>;
export type VideoEditorTranslate = (
  key: string,
  values?: Record<string, string | number>,
) => string;
export type VideoEditorServices = {
  loadSource?: (
    source: VideoEditorSource,
    signal: AbortSignal,
  ) => Promise<EditSource>;
  loadThumbnails?: (url: string, signal: AbortSignal) => Promise<string[]>;
  loadWaveform?: (url: string) => Promise<number[]>;
};
export type VideoEditorExportSettings = {
  resolution: 480 | 720 | 1080;
  format: "mp4" | "mov";
};
export type VideoEditorExportRequest = {
  settings: VideoEditorExportSettings;
  document: VideoEditDocument;
  destination: string;
  signal: AbortSignal;
  onProgress: (percent: number) => void;
};
export type VideoEditorOptions = {
  value: VideoEditDocument;
  sources: VideoEditorSource[];
  onChange: (document: VideoEditDocument) => void;
  readOnly?: boolean;
  autoImport?: boolean;
  services?: VideoEditorServices;
  translate?: VideoEditorTranslate;
  onExport?: (request: VideoEditorExportRequest) => Promise<string | void>;
};
export type VideoEditorProps = VideoEditorOptions & {
  className?: string;
  recommendedResolution?: VideoEditorExportSettings["resolution"];
  exportActions?: { id: string; label: string }[];
  onClose?: () => void;
};

import { useEffect, useRef } from "react";
import type { VideoEditorSource } from "./types";
import type { VideoEditDocument } from "./types";

export function sourceKey(id: string, url: string) {
  return JSON.stringify([id, url]);
}

export function rememberedSources(doc: VideoEditDocument) {
  return [
    ...new Set([
      ...(doc.importedSources ?? []),
      ...doc.clips.flatMap((clip) =>
        clip.kind === "text"
          ? []
          : [sourceKey(clip.source.id, clip.source.url)],
      ),
    ]),
  ];
}

export function useConnectedSources({
  doc,
  sources,
  disabled,
  addSource,
}: {
  doc: VideoEditDocument;
  sources: VideoEditorSource[];
  disabled: boolean;
  addSource: (id: string) => Promise<void>;
}) {
  const attempted = useRef(new Set(rememberedSources(doc)));
  useEffect(() => {
    const remembered = new Set(rememberedSources(doc));
    const connected = new Set(
      sources.map((source) => sourceKey(source.id, source.url)),
    );
    for (const key of attempted.current)
      if (!connected.has(key) && !remembered.has(key))
        attempted.current.delete(key);
    for (const key of remembered) attempted.current.add(key);
    if (disabled) return;
    const source = sources.find(
      (item) =>
        item.url &&
        !remembered.has(sourceKey(item.id, item.url)) &&
        !attempted.current.has(sourceKey(item.id, item.url)),
    );
    if (!source?.url) return;
    // Defer until effect setup settles so StrictMode cleanup cannot consume an import.
    let cancelled = false;
    const key = sourceKey(source.id, source.url);
    queueMicrotask(() => {
      if (cancelled) return;
      attempted.current.add(key);
      void addSource(source.id);
    });
    return () => {
      cancelled = true;
    };
  }, [doc, sources, disabled, addSource]);
}

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";

/** Coalesce pointer updates; callers commit the exact final value on pointerup. */
export function useFrameCallback<Args extends unknown[]>(
  callback: (...args: Args) => void,
) {
  const latest = useRef(callback);
  const pending = useRef<Args | null>(null);
  const frame = useRef<number | null>(null);
  useLayoutEffect(() => {
    latest.current = callback;
  }, [callback]);
  const cancel = useCallback(() => {
    if (frame.current !== null) cancelAnimationFrame(frame.current);
    frame.current = null;
    pending.current = null;
  }, []);
  useEffect(() => cancel, [cancel]);
  const schedule = useCallback((...args: Args) => {
    pending.current = args;
    if (frame.current !== null) return;
    frame.current = requestAnimationFrame(() => {
      frame.current = null;
      const value = pending.current;
      pending.current = null;
      if (value) latest.current(...value);
    });
  }, []);
  return { schedule, cancel };
}

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { defaultTranslate } from "./video-editor-context";
import { editDuration, normalizeEdit } from "./timeline";
import {
  rememberedSources,
  sourceKey,
  useConnectedSources,
} from "./use-connected-sources";
import { loadEditSource } from "./media-metadata";
import { isSubtitle, MAX_SUBTITLES, updateEditClip } from "./subtitles";
import type {
  EditClip,
  VideoEditDocument,
  VideoEditorOptions,
  VideoEditorExportSettings,
} from "./types";

export function useVideoEditor({
  value: doc,
  sources,
  onChange,
  readOnly = false,
  autoImport = false,
  services = {},
  translate: t = defaultTranslate,
  onExport,
}: VideoEditorOptions) {
  const [selected, setSelected] = useState<string | null>(null);
  const [time, setTime] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [busy, setBusy] = useState<"import" | "export" | null>(null);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [failedImports, setFailedImports] = useState<string[]>([]);
  const [history, setHistory] = useState<{
    present: VideoEditDocument;
    past: VideoEditDocument[];
    future: VideoEditDocument[];
  }>({ present: doc, past: [], future: [] });
  const job = useRef<AbortController | null>(null);
  const jobBasis = useRef<{
    doc: VideoEditDocument;
    sources: { id: string; url: string }[];
  } | null>(null);
  const missing = doc.clips.some(
    (c) =>
      c.kind !== "text" &&
      !sources.some((s) => s.id === c.source.id && s.url === c.source.url),
  );
  useLayoutEffect(() => {
    const basis = jobBasis.current;
    if (
      job.current &&
      basis &&
      (readOnly ||
        basis.doc !== doc ||
        basis.sources.some(
          (source) =>
            !sources.some(
              (item) => item.id === source.id && item.url === source.url,
            ),
        ))
    )
      job.current.abort();
  }, [doc, sources, readOnly]);
  useEffect(
    () => () => {
      job.current?.abort();
    },
    [],
  );
  const stop = useCallback(() => setPlaying(false), []);
  const previewError = useCallback(
    () => setError(t("videoEditor.mediaError")),
    [t],
  );
  const write = (next: VideoEditDocument) => {
    if (readOnly) return;
    onChange(next);
    setPlaying(false);
    setTime((current) => Math.min(current, editDuration(next)));
  };
  const commit = (next: VideoEditDocument) => {
    if (readOnly || job.current || next === doc) return;
    const subtitleCount = next.clips.filter(isSubtitle).length;
    if (
      subtitleCount > MAX_SUBTITLES &&
      subtitleCount > doc.clips.filter(isSubtitle).length
    ) {
      setError(t("videoEditor.subtitleLimit", { count: MAX_SUBTITLES }));
      return;
    }
    const normalized = normalizeEdit({
      ...next,
      importedSources: [
        ...new Set([...rememberedSources(doc), ...rememberedSources(next)]),
      ],
    });
    setHistory((h) => ({
      present: normalized,
      past: [...(h.present === doc ? h.past : []), doc].slice(-50),
      future: [],
    }));
    write(normalized);
  };
  const undo = () => {
    if (readOnly || history.present !== doc || !history.past.length || busy)
      return;
    const next = {
      ...history.past[history.past.length - 1]!,
      importedSources: rememberedSources(doc),
    };
    setHistory({
      present: next,
      past: history.past.slice(0, -1),
      future: [doc, ...history.future],
    });
    write(next);
  };
  const redo = () => {
    if (readOnly || history.present !== doc || !history.future.length || busy)
      return;
    const next = {
      ...history.future[0],
      importedSources: rememberedSources(doc),
    };
    setHistory({
      present: next,
      past: [...history.past, doc],
      future: history.future.slice(1),
    });
    write(next);
  };
  const updateClip = (clip: EditClip) => {
    const original = doc.clips.find((item) => item.id === clip.id);
    if (
      clip.kind !== "text" &&
      original &&
      original.kind !== "text" &&
      (clip.fadeIn !== original.fadeIn || clip.fadeOut !== original.fadeOut)
    ) {
      commit(updateEditClip(doc, { ...clip, fadeRange: undefined }));
      return;
    }
    commit(updateEditClip(doc, clip));
  };
  const addSource = async (id: string, automatic = false) => {
    if (job.current || readOnly) return;
    const source = sources.find((s) => s.id === id);
    if (!source?.url || (source.kind !== "video" && source.kind !== "audio"))
      return;
    const controller = new AbortController();
    const key = sourceKey(source.id, source.url);
    job.current = controller;
    jobBasis.current = { doc, sources: [{ id: source.id, url: source.url }] };
    setBusy("import");
    if (!automatic) setError(null);
    setPlaying(false);
    try {
      const media = await (services.loadSource ?? loadEditSource)(
        {
          id: source.id,
          label: source.label,
          url: source.url,
          kind: source.kind,
        },
        controller.signal,
      );
      controller.signal.throwIfAborted();
      const clip: EditClip = {
        id: crypto.randomUUID(),
        kind: media.kind,
        source: media,
        start: media.kind === "audio" && !automatic ? time : 0,
        in: 0,
        out: media.duration,
        speed: 1,
        volume: 1,
        muted: false,
        fadeIn: 0,
        fadeOut: 0,
      };
      job.current = null;
      commit({ ...doc, clips: [...doc.clips, clip] });
      setFailedImports((failed) => failed.filter((item) => item !== key));
      if (
        !failedImports.some(
          (item) =>
            item !== key &&
            sources.some((source) => sourceKey(source.id, source.url) === item),
        )
      )
        setError(null);
      setSelected(clip.id);
    } catch {
      setFailedImports((failed) => [...new Set([...failed, key])]);
      if (!controller.signal.aborted) setError(t("videoEditor.mediaError"));
    } finally {
      if (job.current === controller) job.current = null;
      setBusy(null);
    }
  };
  useConnectedSources({
    doc,
    sources,
    disabled: !autoImport || Boolean(busy) || readOnly,
    addSource: (id) => addSource(id, true),
  });
  const exportVideo = async (
    destination = "download",
    settings: VideoEditorExportSettings = { resolution: 1080, format: "mp4" },
  ) => {
    if (job.current || readOnly || missing || !onExport) return;
    const controller = new AbortController();
    job.current = controller;
    jobBasis.current = {
      doc,
      sources: doc.clips.flatMap((c) =>
        c.kind === "text" ? [] : [{ id: c.source.id, url: c.source.url }],
      ),
    };
    setBusy("export");
    setProgress(0);
    setError(null);
    setPlaying(false);
    try {
      const result = await onExport({
        document: doc,
        settings,
        destination,
        signal: controller.signal,
        onProgress: setProgress,
      });
      controller.signal.throwIfAborted();
      setProgress(100);
      return result ?? destination;
    } catch {
      if (!controller.signal.aborted) setError(t("videoEditor.exportError"));
    } finally {
      if (job.current === controller) job.current = null;
      setBusy(null);
    }
  };
  const cancel = useCallback(() => job.current?.abort(), []);
  const remembered = new Set(rememberedSources(doc));
  const retrySource = sources.find((source) => {
    const key = sourceKey(source.id, source.url);
    return failedImports.includes(key) && !remembered.has(key);
  });
  return {
    doc,
    sources,
    selected,
    setSelected,
    time,
    setTime,
    playing,
    setPlaying,
    stop,
    previewError,
    busy,
    progress,
    error,
    canRetryImport: Boolean(retrySource),
    retryImport: () => retrySource && addSource(retrySource.id),
    missing,
    readOnly,
    canExport: Boolean(onExport),
    commit,
    updateClip,
    addSource,
    exportVideo,
    undo,
    redo,
    canUndo: history.present === doc && history.past.length > 0,
    canRedo: history.present === doc && history.future.length > 0,
    cancel,
  };
}

import { memo, useEffect, useState } from "react";
import type { MediaClip, VideoEditorServices } from "./types";

function VideoClipStripView({
  clip,
  width,
  visibleFrom = 0,
  visibleTo = width,
  loadThumbnails,
}: {
  clip: MediaClip;
  width: number;
  visibleFrom?: number;
  visibleTo?: number;
  loadThumbnails?: VideoEditorServices["loadThumbnails"];
}) {
  const [strip, setStrip] = useState<{ url: string; frames: string[] } | null>(
    null,
  );
  useEffect(() => {
    if (!loadThumbnails) return;
    const controller = new AbortController();
    void loadThumbnails(clip.source.url, controller.signal)
      .then((frames) => {
        if (!controller.signal.aborted)
          setStrip({ url: clip.source.url, frames });
      })
      .catch(() => {
        // Thumbnails are optional; the clip label remains usable when CORS blocks extraction.
      });
    return () => controller.abort();
  }, [clip.source.url, loadThumbnails]);
  if (!strip || strip.url !== clip.source.url || !strip.frames.length)
    return (
      <span className="truncate px-3 text-[color:var(--ui-text-secondary)]">
        {clip.source.label}
      </span>
    );
  const count = Math.max(1, Math.ceil(width / 96));
  const tileWidth = width / count;
  const first = Math.max(0, Math.floor(visibleFrom / tileWidth));
  const last = Math.min(count, Math.ceil(visibleTo / tileWidth));
  const visible = Array.from(
    { length: Math.max(0, last - first) },
    (_, offset) => {
      const index = first + offset;
      const at = clip.in + ((clip.out - clip.in) * (index + 0.5)) / count;
      return strip.frames[
        Math.min(
          strip.frames.length - 1,
          Math.floor((at / clip.source.duration) * strip.frames.length),
        )
      ];
    },
  );
  return (
    <span
      className="pointer-events-none absolute inset-0 flex overflow-hidden"
      aria-hidden="true"
    >
      {visible.map((src, index) => (
        <img
          key={first + index}
          src={src}
          alt=""
          draggable={false}
          className="absolute h-full object-cover"
          style={{ left: (first + index) * tileWidth, width: tileWidth }}
        />
      ))}
    </span>
  );
}

export const VideoClipStrip = memo(VideoClipStripView);

import { createContext, useContext } from "react";
import type { VideoEditorServices, VideoEditorTranslate } from "./types";
import { defaultMessages } from "./messages";

export const defaultTranslate: VideoEditorTranslate = (key, values) => {
  const message =
    defaultMessages[
      key.replace(/^videoEditor\./, "") as keyof typeof defaultMessages
    ] ?? key;
  return message.replace(/\{(\w+)\}/g, (token, name: string) =>
    String(values?.[name] ?? token),
  );
};
export const VideoEditorContext = createContext<{
  t: VideoEditorTranslate;
  services: VideoEditorServices;
}>({ t: defaultTranslate, services: {} });
export function useI18n() {
  return useContext(VideoEditorContext);
}
export function useVideoEditorServices() {
  return useContext(VideoEditorContext).services;
}

